window.TREE={"subject":"Area I · Individuals and Personal Financial Planning","key":"tcp_area1_individuals","brand":"Terra Prep","area":"I","law_asof":"2026-09-29","parts":[{"no":1,"name":"Area I · Individuals and Personal Financial Planning","chs":["1-01","1-02","1-03","1-04"],"color":"--fam-geo"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"Individual compliance and tax planning for gross income, AGI, taxable income and estimated taxes","grp":"A","nodes":[1,2,3,4,5,6,7,8]},{"key":"1-02","part":1,"no":2,"name":"Compliance for passive activity and at-risk loss limitations (excluding tax credit implications)","grp":"B","nodes":[9,10,11]},{"key":"1-03","part":1,"no":3,"name":"Gift taxation compliance and planning","grp":"C","nodes":[12,13,14,15]},{"key":"1-04","part":1,"no":4,"name":"Personal financial planning for individuals","grp":"D","nodes":[16,17,18,19,20,21]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"Gross income items","name":"Gross income items","vol":11,"q":11,"cs":0,"law":0,"grp":"A"},{"no":2,"part":1,"ch":1,"title":"AMT","name":"AMT","vol":4,"q":4,"cs":0,"law":0,"grp":"A"},{"no":3,"part":1,"ch":1,"title":"Kiddie tax","name":"Kiddie tax","vol":2,"q":2,"cs":0,"law":0,"grp":"A"},{"no":4,"part":1,"ch":1,"title":"Timing planning","name":"Timing planning","vol":5,"q":5,"cs":0,"law":0,"grp":"A"},{"no":5,"part":1,"ch":1,"title":"FSA/HSA","name":"FSA/HSA","vol":4,"q":4,"cs":0,"law":0,"grp":"A"},{"no":6,"part":1,"ch":1,"title":"Itemized vs standard deduction","name":"Itemized vs standard deduction","vol":4,"q":4,"cs":0,"law":0,"grp":"A"},{"no":7,"part":1,"ch":1,"title":"Estimated tax","name":"Estimated tax","vol":3,"q":3,"cs":0,"law":0,"grp":"A"},{"no":8,"part":1,"ch":1,"title":"Charitable giving","name":"Charitable giving","vol":3,"q":3,"cs":0,"law":0,"grp":"A"},{"no":9,"part":1,"ch":2,"title":"At-risk limitation","name":"At-risk limitation","vol":5,"q":5,"cs":0,"law":0,"grp":"B"},{"no":10,"part":1,"ch":2,"title":"Passive activity loss","name":"Passive activity loss","vol":5,"q":5,"cs":0,"law":0,"grp":"B"},{"no":11,"part":1,"ch":2,"title":"Suspended losses","name":"Suspended losses","vol":2,"q":2,"cs":0,"law":0,"grp":"B"},{"no":12,"part":1,"ch":3,"title":"Gift tax deductions/exclusions","name":"Gift tax deductions/exclusions","vol":3,"q":3,"cs":0,"law":0,"grp":"C"},{"no":13,"part":1,"ch":3,"title":"Unified transfer tax system","name":"Unified transfer tax system","vol":1,"q":1,"cs":0,"law":0,"grp":"C"},{"no":14,"part":1,"ch":3,"title":"Taxable gifts","name":"Taxable gifts","vol":4,"q":4,"cs":0,"law":0,"grp":"C"},{"no":15,"part":1,"ch":3,"title":"Gifting for planning","name":"Gifting for planning","vol":5,"q":5,"cs":0,"law":0,"grp":"C"},{"no":16,"part":1,"ch":4,"title":"Retirement plans","name":"Retirement plans","vol":9,"q":9,"cs":0,"law":0,"grp":"D"},{"no":17,"part":1,"ch":4,"title":"Investment risk","name":"Investment risk","vol":1,"q":1,"cs":0,"law":0,"grp":"D"},{"no":18,"part":1,"ch":4,"title":"Investment ROI","name":"Investment ROI","vol":2,"q":2,"cs":0,"law":0,"grp":"D"},{"no":19,"part":1,"ch":4,"title":"Education funding","name":"Education funding","vol":2,"q":2,"cs":0,"law":0,"grp":"D"},{"no":20,"part":1,"ch":4,"title":"Insurance planning","name":"Insurance planning","vol":1,"q":1,"cs":0,"law":0,"grp":"D"},{"no":21,"part":1,"ch":4,"title":"Asset ownership & beneficiary","name":"Asset ownership & beneficiary","vol":1,"q":1,"cs":0,"law":0,"grp":"D"}],"stat":{"parts":1,"chs":4,"nodes":21,"q":77}};
window.QBANK={"1":[{"i":"TCP-I-A-0001","t":"Marisol Duran, an employee, holds two stock options. Both were granted at a strike price equal to the stock's value on the grant date, neither has a readily ascertainable fair market value at grant, and both are exercised after they vest. Marisol holds the shares from each exercise for more than two years after grant and more than one year after exercise before selling. Which statement correctly describes the regular income tax results?","mc":{"s":"Marisol Duran, an employee, holds two stock options. Both were granted at a strike price equal to the stock's value on the grant date, neither has a readily ascertainable fair market value at grant, and both are exercised after they vest. Marisol holds the shares from each exercise for more than two years after grant and more than one year after exercise before selling. Which statement correctly describes the regular income tax results?","d":"","o":["Both options give compensation income at the grant date equal to the strike price, because the grant is the taxable event","The nonqualified option gives compensation income at exercise equal to the spread, but the incentive option gives none until sale","Neither option produces regular tax income until the shares are sold, and all of the gain on each is taxed as long-term capital gain","The incentive option produces compensation income at exercise, while the nonqualified option is not taxed until the shares are sold"],"a":2,"cite":"IRC §83(a); IRC §421(a); IRC §422(a); Reg. §1.83-7","rat":"A nonqualified option is taxed at exercise on the spread as wages.","ex":["Options without a readily ascertainable value are not taxed at grant. Grant is a taxable event only in rare cases where the option itself has a readily ascertainable fair market value.","A nonqualified option is taxed at exercise on the spread as wages. An incentive stock option that meets the holding requirements is not taxed at exercise for regular tax, and the entire gain on sale is long-term capital gain.","This is right only for the incentive option. The spread on a nonqualified option is compensation income at exercise, and only later appreciation is capital gain.","Reverses the two options. The nonqualified option is the one taxed at exercise; the incentive option's spread is an AMT adjustment, not regular income."],"wt":["concept","","concept","trap"],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A nonqualified option is taxed at exercise on the spread; a qualifying incentive stock option has no regular tax at exercise and its sale gain is capital gain.","from":"2026-01-01"}},{"i":"TCP-I-A-0002","t":"In 2026 Priya Rao, an employee, exercised nonqualified stock options on 1,500 shares at a strike price of $32 per share when the stock's fair market value was $58 per share. She held the shares for 18 months and then sold all of them for $71 per share. What is her long-term capital gain on the sale?","mc":{"s":"In 2026 Priya Rao, an employee, exercised nonqualified stock options on 1,500 shares at a strike price of $32 per share when the stock's fair market value was $58 per share. She held the shares for 18 months and then sold all of them for $71 per share. What is her long-term capital gain on the sale?","d":"","o":["$19,500","$39,000","$58,500","$106,500"],"a":1,"cite":"IRC §83(a); IRC §1012; Reg. §1.83-4(b)","rat":"The spread at exercise ($39,000) was compensation income, so her basis is the fair market value at exercise, $58 per share.","ex":["The spread at exercise ($39,000) was compensation income, so her basis is the fair market value at exercise, $58 per share. The gain is 1,500 x ($71 - $58) = $19,500.","This is the compensation income recognized at exercise, not the gain on the later sale.","Uses the strike price as basis. The spread was already taxed as wages at exercise, so it is added to basis and cannot be taxed again as capital gain.","Treats the full sale proceeds as gain. Basis is not zero; it is the fair market value at exercise."],"wt":["","concept","concept","calc"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Basis of stock from a nonqualified option is the strike price plus the spread taxed at exercise; only later appreciation is capital gain.","from":"2026-01-01","calc":1,"steps":["Basis per share = fair market value at exercise = $58 (strike $32 + $26 spread taxed as wages)","Gain per share = 71 - 58 = 13","1,500 x 13 = $19,500"]}},{"i":"TCP-I-A-0006","t":"On April 1, 2026, Leo Marsh lent his niece $250,000 for use in a business. The loan is payable on demand, bears no interest, and remained outstanding through December 31, 2026. Assume the applicable blended rate for 2026 is 4.0%, and that the below-market gift loan rules are not limited by the borrower's investment income. How much interest income must Leo report for 2026?","mc":{"s":"On April 1, 2026, Leo Marsh lent his niece $250,000 for use in a business. The loan is payable on demand, bears no interest, and remained outstanding through December 31, 2026. Assume the applicable blended rate for 2026 is 4.0%, and that the below-market gift loan rules are not limited by the borrower's investment income. How much interest income must Leo report for 2026?","d":"","o":["$0","$2,500","$7,500","$10,000"],"a":3,"cite":"IRC §7872(a); IRC §7872(d); Reg. §1.7872-13; IRC §7872(c)(2)","rat":"A below-market gift loan above $10,000 is not exempt, and above $100,000 the investment income cap does not apply: $250,000 x 4.0% x 9/12 = $7,500 of imputed interest for the period outstanding.","ex":["Assumes no income arises when no interest is charged. This gift loan is above the $10,000 exemption and above $100,000, so the investment income cap does not apply and imputed interest income arises.","Uses the three months before the loan was made (January through March) instead of the nine months it was outstanding.","A below-market gift loan above $10,000 is not exempt, and above $100,000 the investment income cap does not apply: $250,000 x 4.0% x 9/12 = $7,500 of imputed interest for the period outstanding. Leo reports it as interest income and is treated as making a gift of the same amount.","Uses a full year of imputed interest. The loan was outstanding for nine months."],"wt":["concept","calc","","calc"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Below-market demand loans have imputed interest at the applicable rate for the period outstanding; a gift loan of $10,000 or less is exempt, and the borrower's net investment income cap applies only to gift loans of $100,000 or less.","from":"2026-01-01","calc":1,"steps":["Imputed interest = 250,000 x 4.0% x 9/12 = $7,500"]}},{"i":"TCP-I-A-0007","t":"Naomi Pratt, a U.S. citizen, lived and worked in a foreign country for all of 2026 and qualifies for the foreign earned income exclusion under the bona fide residence test. She earned $150,000 from her foreign employer and received $10,000 of interest from a U.S. bank. Assume the 2026 maximum exclusion is $132,900, she elects the exclusion, and she has no foreign housing costs. What amount of gross income does she include on her 2026 return?","mc":{"s":"Naomi Pratt, a U.S. citizen, lived and worked in a foreign country for all of 2026 and qualifies for the foreign earned income exclusion under the bona fide residence test. She earned $150,000 from her foreign employer and received $10,000 of interest from a U.S. bank. Assume the 2026 maximum exclusion is $132,900, she elects the exclusion, and she has no foreign housing costs. What amount of gross income does she include on her 2026 return?","d":"","o":["$10,000","$17,100","$27,100","$160,000"],"a":3,"cite":"IRC §911(a); IRC §911(b)(2); Pub 54","rat":"The excludable foreign earned income is the lesser of the exclusion limit and earned income.","ex":["Excludes all of the wages, as if the exclusion had no dollar limit.","Excludes the U.S. interest along with the wages. The exclusion applies only to foreign earned income.","The excludable foreign earned income is the lesser of the exclusion limit and earned income. $150,000 - $132,900 = $17,100 of wages remains, plus $10,000 of interest: $27,100.","Ignores the foreign earned income exclusion."],"wt":["limit","concept","","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The foreign earned income exclusion removes only foreign earned income, up to the annual dollar limit; other income stays in gross income.","from":"2026-01-01","calc":1,"steps":["Wages not excluded = 150,000 - 132,900 = $17,100","Add U.S. interest 10,000: $27,100"]}},{"i":"TCP-I-A-0022","t":"In 2026 Cora Diaz exercised incentive stock options on 1,000 shares at $20 per share when the shares were worth $50. Three months later, when the price had dropped to $42, she sold all the shares. What amount of compensation income results from the sale for regular tax purposes?","mc":{"s":"In 2026 Cora Diaz exercised incentive stock options on 1,000 shares at $20 per share when the shares were worth $50. Three months later, when the price had dropped to $42, she sold all the shares. What amount of compensation income results from the sale for regular tax purposes?","d":"","o":["$8,000","$22,000","$30,000","$42,000"],"a":2,"cite":"IRC §421(b); IRC §422(a)(1); Reg. §1.421-2(b)","rat":"The sale within one year of exercise is a disqualifying disposition.","ex":["This is the decline in value after exercise, not the income.","The sale within one year of exercise is a disqualifying disposition. Compensation income is the lesser of the spread at exercise ($30,000) or the gain on sale ($22,000): $22,000. There is no additional capital gain or loss.","Uses the spread at exercise even though the sale price is lower. The compensation income is limited to the actual gain.","Treats the full sale proceeds as compensation instead of only the gain over the exercise price."],"wt":["concept","","limit","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"On a disqualifying disposition of ISO stock, compensation income is the lesser of the spread at exercise or the gain realized.","from":"2026-01-01","calc":1,"steps":["Spread at exercise = (50 - 20) x 1,000 = $30,000","Gain on sale = (42 - 20) x 1,000 = $22,000","Compensation income = lesser = $22,000"]}},{"i":"TCP-I-A-0023","t":"Ken Alder received 5,000 shares of restricted stock from his employer in 2026 for no payment. The shares were worth $4 each at grant and vest in 2028, when they will be worth $15 each. Ken can either make a timely election to be taxed at grant or not make it. By how much does the election reduce his ordinary compensation income over the life of the award?","mc":{"s":"Ken Alder received 5,000 shares of restricted stock from his employer in 2026 for no payment. The shares were worth $4 each at grant and vest in 2028, when they will be worth $15 each. Ken can either make a timely election to be taxed at grant or not make it. By how much does the election reduce his ordinary compensation income over the life of the award?","d":"","o":["$20,000","$55,000","$75,000","$110,000"],"a":2,"cite":"IRC §83(b); Reg. §1.83-2; Pub 525","rat":"With the election he has compensation income of 5,000 x $4 = $20,000 in 2026.","ex":["This is the ordinary income he reports with the election, not the reduction.","With the election he has compensation income of 5,000 x $4 = $20,000 in 2026. Without it he has 5,000 x $15 = $75,000 at vesting. The appreciation, $55,000, is capital gain when sold under the election, so ordinary income is reduced by that amount.","This is the ordinary income he reports without the election.","Double counts the appreciation."],"wt":["trap","","trap","calc"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A section 83(b) election taxes the restricted stock's value at grant; later appreciation becomes capital gain instead of compensation.","from":"2026-01-01","calc":1,"steps":["No election: ordinary income at vesting = 5,000 x 15 = $75,000","Election: ordinary income at grant = 5,000 x 4 = $20,000","Reduction = $75,000 - $20,000 = $55,000"]}},{"i":"TCP-I-A-0024","t":"Nadia Farrow, a single taxpayer, bought her main home in 2025 and lived in it for exactly 12 months before her employer moved her to a location that is 200 miles farther from the home. She sold the home in 2026 at a gain of $180,000. She has not used the home-sale exclusion before. What amount of the gain is taxable?","mc":{"s":"Nadia Farrow, a single taxpayer, bought her main home in 2025 and lived in it for exactly 12 months before her employer moved her to a location that is 200 miles farther from the home. She sold the home in 2026 at a gain of $180,000. She has not used the home-sale exclusion before. What amount of the gain is taxable?","d":"","o":["$0","$55,000","$125,000","$180,000"],"a":2,"cite":"IRC §121(c); Reg. §1.121-3; Pub 523","rat":"She fails the two-year tests, but the move for employment qualifies for a reduced exclusion of $250,000 x 12/24 = $125,000.","ex":["Applies the full exclusion of $250,000. The exclusion is reduced in proportion to the shortfall in the ownership and use period.","She fails the two-year tests, but the move for employment qualifies for a reduced exclusion of $250,000 x 12/24 = $125,000. The taxable gain is $180,000 - $125,000 = $55,000.","This is the reduced exclusion, not the taxable gain.","Allows no exclusion. A job-related move gives a prorated exclusion even when the two-year test is not met."],"wt":["limit","","trap","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A home sold early because of a change in place of employment qualifies for a prorated exclusion based on months of ownership and use out of 24.","from":"2026-01-01","calc":1,"steps":["Reduced exclusion = 250,000 x 12/24 = $125,000","Taxable gain = 180,000 - $125,000 = $55,000"]}},{"i":"TCP-I-A-0025","t":"Jim Ward transferred stock with a basis of $20,000 and a fair market value of $90,000 to his former spouse in 2026 under a divorce decree, as part of the property settlement. Which statement describes the tax result?","mc":{"s":"Jim Ward transferred stock with a basis of $20,000 and a fair market value of $90,000 to his former spouse in 2026 under a divorce decree, as part of the property settlement. Which statement describes the tax result?","d":"","o":["Jim recognizes no gain, and his former spouse takes a $20,000 carryover basis in the stock","Jim recognizes a $70,000 gain, and his former spouse takes a basis of $90,000","Jim recognizes no gain, and his former spouse takes a $90,000 stepped-up basis","Jim recognizes no gain only if the transfer occurs within one year after the marriage ends; otherwise it is a taxable sale"],"a":1,"cite":"IRC §1041(a); IRC §1041(b); Reg. §1.1041-1T(b)","rat":"A transfer between former spouses incident to divorce is treated as a gift, so there is no gain or loss, and the recipient takes the transferor's basis.","ex":["A transfer between former spouses incident to divorce is treated as a gift, so there is no gain or loss, and the recipient takes the transferor's basis.","Applies the ordinary sale rules. Transfers incident to divorce are nonrecognition transfers.","There is no step-up. The recipient takes the transferor's basis, so the built-in gain is taxed when the spouse sells.","The one-year period is a safe harbor, and transfers made within six years under the divorce instrument are also covered."],"wt":["","concept","concept","limit"],"tags":{"area":"I","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Property transfers between spouses or incident to divorce are nonrecognition events with carryover basis.","from":"2026-01-01"}},{"i":"TCP-I-A-0029","t":"Kevin Doyle, age 47, is covered by $250,000 of employer-paid group-term life insurance for all of 2026. He paid $100 toward the cost of the coverage during the year. Assume the uniform premium table cost for his age is $0.15 per month per $1,000 of coverage. What amount is included in his 2026 gross income?","mc":{"s":"Kevin Doyle, age 47, is covered by $250,000 of employer-paid group-term life insurance for all of 2026. He paid $100 toward the cost of the coverage during the year. Assume the uniform premium table cost for his age is $0.15 per month per $1,000 of coverage. What amount is included in his 2026 gross income?","d":"","o":["$260","$350","$360","$450"],"a":1,"cite":"IRC §79(a); Reg. §1.79-3(d); Pub 15-B","rat":"The first $50,000 of group-term coverage is excluded.","ex":["The first $50,000 of group-term coverage is excluded. The cost of the remaining $200,000 is ($200,000 / $1,000) x $0.15 x 12 = $360, reduced by the $100 he paid: $260.","Ignores the $50,000 exclusion and treats all coverage as taxable.","Does not reduce the imputed cost by the amount Kevin paid.","Ignores both the $50,000 exclusion and the employee payment."],"wt":["","concept","calc","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Group-term life coverage above $50,000 creates imputed income from the table cost, reduced by the employee's payments.","from":"2026-01-01","calc":1,"steps":["Coverage over $50,000 = $200,000","Table cost = $200,000 / 1,000 x 0.15 x 12 = $360","Less employee payment 100: $260"]}},{"i":"TCP-I-A-0030","t":"Each of the following individuals is a U.S. citizen who earned $120,000 in 2026 for services performed in a foreign country. Who may claim the foreign earned income exclusion?","mc":{"s":"Each of the following individuals is a U.S. citizen who earned $120,000 in 2026 for services performed in a foreign country. Who may claim the foreign earned income exclusion?","d":"","o":["Mark, who was present abroad for 340 full days but kept his tax home in the United States for the year","Lena, who had a foreign tax home and was present abroad for 334 full days in a 12-month period ending December 31","Nia, a civilian employee of a U.S. federal agency who was paid by the agency and lived abroad all year long","Omar, who had a foreign tax home and was present abroad for 320 full days in a 12-month period ending December 31"],"a":2,"cite":"IRC §911(d)(1); IRC §911(b)(1)(B); Pub 54","rat":"The physical presence test requires 330 full days in a foreign country in a 12-month period, along with a foreign tax home.","ex":["The exclusion requires a foreign tax home. Mark's tax home stayed in the United States.","The physical presence test requires 330 full days in a foreign country in a 12-month period, along with a foreign tax home.","Amounts paid by the United States or its agencies to employees are not foreign earned income for the exclusion.","The physical presence test needs 330 full days. 320 days does not qualify unless he meets the bona fide residence test, which is not stated."],"wt":["concept","","trap","limit"],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The exclusion requires a foreign tax home plus either bona fide residence or 330 full days abroad in a 12-month period, and excludes U.S. government pay.","from":"2026-01-01"}},{"i":"TCP-I-A-0031","t":"Hugo Brandt, single, bought a house on January 1, 2018 for $400,000 and rented it to tenants for exactly 48 months. On January 1, 2022 he moved in and has lived there as his main home since. He claimed $48,000 of depreciation during the rental period. He can sell the house on December 31, 2026 (owned 108 months) or keep living in it and sell on December 31, 2028 (owned 132 months). Either sale would bring a net amount realized of $700,000, and there are no other basis changes. How much less taxable gain does Hugo recognize by waiting until 2028?","mc":{"s":"Hugo Brandt, single, bought a house on January 1, 2018 for $400,000 and rented it to tenants for exactly 48 months. On January 1, 2022 he moved in and has lived there as his main home since. He claimed $48,000 of depreciation during the rental period. He can sell the house on December 31, 2026 (owned 108 months) or keep living in it and sell on December 31, 2028 (owned 132 months). Either sale would bring a net amount realized of $700,000, and there are no other basis changes. How much less taxable gain does Hugo recognize by waiting until 2028?","d":"","o":["$24,242","$28,121","$133,333","$181,333"],"a":1,"cite":"IRC §121(b)(5); IRC §121(d)(6); Reg. §1.121-1(b)(4)","rat":"The depreciation gain of $48,000 is taxable either way.","ex":["The depreciation gain of $48,000 is taxable either way. The remaining $300,000 of gain is allocated to nonqualified use (the 48 rental months before he moved in) by months owned: 48/108 in 2026 and 48/132 in 2028. The gain that is allocated to home use is under the $250,000 exclusion in both years, so only the allocation changes: $300,000 x (48/108 - 48/132) = $24,242.","Allocates the entire $348,000 of gain by months. The $48,000 of gain from depreciation is taxable in full and is taken out before the nonqualified use allocation, so it cannot be spread by months.","This is the nonqualified use gain if he sells in 2026, not the reduction from waiting. The 2028 sale also has an allocation ($109,091), so only the difference in the two allocations is saved.","This is his total taxable gain if he sells in 2026 (allocated gain plus the depreciation). Waiting does not remove that, it only reduces the allocated part."],"wt":["","calc","trap","trap"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Gain on a home sale allocated to periods of nonqualified use, such as rental use before it became the main home, is not excludable, and gain equal to depreciation claimed after May 6, 1997 is also not excludable.","from":"2026-01-01","calc":1,"steps":["Total gain = 700,000 - (400,000 - 48,000) = 348,000","Depreciation gain of 48,000 is not excludable; remaining gain = 348,000 - 48,000 = 300,000","Nonqualified fraction: 48/108 for a 2026 sale and 48/132 for a 2028 sale","Allocated (taxable) gain: 300,000 x 48/108 = 133,333 versus 300,000 x 48/132 = 109,091","Gain allocated to qualified use (166,667 or 190,909) is below the 250,000 exclusion, so difference = 133,333 - 109,091 = 24,242"]}}],"2":[{"i":"TCP-I-A-0003","t":"In 2026 Ben Ortiz exercised incentive stock options on 2,000 shares at $20 per share when the shares were worth $55 each. He still held all the shares on December 31, 2026. By how much does the exercise increase his 2026 alternative minimum taxable income compared with his regular taxable income?","mc":{"s":"In 2026 Ben Ortiz exercised incentive stock options on 2,000 shares at $20 per share when the shares were worth $55 each. He still held all the shares on December 31, 2026. By how much does the exercise increase his 2026 alternative minimum taxable income compared with his regular taxable income?","d":"","o":["$70,000","$110,000","$140,000","$150,000"],"a":1,"cite":"IRC §56(b)(3); IRC §422; Form 6251 instructions","rat":"The spread (2,000 x ($55 - $20) = $70,000) is an AMT adjustment in the year the shares become transferable and not subject to a substantial risk of forfeiture, even though it is not regular income.","ex":["The spread (2,000 x ($55 - $20) = $70,000) is an AMT adjustment in the year the shares become transferable and not subject to a substantial risk of forfeiture, even though it is not regular income.","This is the total fair market value of the shares. Only the spread over the exercise price is an adjustment.","Doubles the total spread, which has no basis in the rule.","Adds the aggregate exercise price and value."],"wt":["","concept","calc","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"The bargain element of an incentive stock option is an AMT adjustment in the year of exercise when the shares are held.","from":"2026-01-01","calc":1,"steps":["Spread per share = 55 - 20 = 35","2,000 x 35 = $70,000"]}},{"i":"TCP-I-A-0004","t":"Dana Whit, single, itemizes deductions for 2026. Which of the following amounts must be added back to regular taxable income in computing Dana's alternative minimum taxable income?","mc":{"s":"Dana Whit, single, itemizes deductions for 2026. Which of the following amounts must be added back to regular taxable income in computing Dana's alternative minimum taxable income?","d":"","o":["The spread on incentive stock options exercised and still held at year end","Interest on a general obligation bond issued by Dana's home state and held for years","Cash contributions to a public charity that were deducted on Schedule A this year","Qualified interest paid on the acquisition debt of Dana's main home"],"a":1,"cite":"IRC §56(b)(3); IRC §57(a)(5); IRC §56(b)(1)","rat":"The spread on incentive stock options exercised and held is an AMT adjustment that increases AMTI.","ex":["The spread on incentive stock options exercised and held is an AMT adjustment that increases AMTI.","Interest on ordinary governmental bonds remains excluded for AMT. Only interest on specified private activity bonds is a preference item.","Charitable contributions are allowed in computing AMTI.","Interest on acquisition debt for a qualified residence is allowed for AMT."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Incentive stock option spreads (held at year end) and private activity bond interest increase AMTI; ordinary tax-exempt interest and charitable gifts do not.","from":"2026-01-01"}},{"i":"TCP-I-A-0005","t":"Erin Cole, a single taxpayer, has 2026 alternative minimum taxable income of $400,000 before the exemption. Assume her AMT exemption is $90,100 with no phase-out, the AMT rates are 26% on the first $244,500 of AMTI after the exemption and 28% on the excess, and her regular tax liability is $70,000. What is her alternative minimum tax for 2026?","mc":{"s":"Erin Cole, a single taxpayer, has 2026 alternative minimum taxable income of $400,000 before the exemption. Assume her AMT exemption is $90,100 with no phase-out, the AMT rates are 26% on the first $244,500 of AMTI after the exemption and 28% on the excess, and her regular tax liability is $70,000. What is her alternative minimum tax for 2026?","d":"","o":["$10,574","$11,882","$16,772","$81,882"],"a":2,"cite":"IRC §55(a); IRC §55(b)(1); Form 6251 instructions","rat":"AMTI after exemption = $309,900.","ex":["Applies 26% to all AMTI after the exemption and ignores the 28% band above the breakpoint.","AMTI after exemption = $309,900. Tentative minimum tax = 26% x $244,500 + 28% x $65,400 = $81,882. AMT is the excess over regular tax: $81,882 - $70,000 = $11,882.","Applies 28% to all AMTI after the exemption instead of using 26% on the first band.","This is the tentative minimum tax. The AMT is only the excess of tentative minimum tax over regular tax."],"wt":["calc","","calc","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"AMT equals the excess of tentative minimum tax (26% and 28% bands on AMTI less exemption) over regular tax.","from":"2026-01-01","calc":1,"steps":["AMTI less exemption = 400,000 - 90,100 = $309,900","Tentative minimum tax = 0.26 x 244,500 + 0.28 x $65,400 = $81,882","AMT = $81,882 - 70,000 = $11,882"]}},{"i":"TCP-I-A-0028","t":"Ben Ortiz's 2026 and 2027 alternative minimum taxable income, before any incentive stock option adjustment, is expected to be $200,000 each year, and his regular tax is $45,000 each year. He holds vested options on 20,000 shares with a $10 per share spread that he will hold after exercise. He can exercise all of them in 2026 or exercise 10,000 shares in each of 2026 and 2027. Assume the exemption is $90,100 with no phase-out, the AMT rate is 26% on the first $244,500 of AMTI after the exemption and 28% above, and ignore the AMT credit. How much total AMT does splitting the exercises save over the two years?","mc":{"s":"Ben Ortiz's 2026 and 2027 alternative minimum taxable income, before any incentive stock option adjustment, is expected to be $200,000 each year, and his regular tax is $45,000 each year. He holds vested options on 20,000 shares with a $10 per share spread that he will hold after exercise. He can exercise all of them in 2026 or exercise 10,000 shares in each of 2026 and 2027. Assume the exemption is $90,100 with no phase-out, the AMT rate is 26% on the first $244,500 of AMTI after the exemption and 28% above, and ignore the AMT credit. How much total AMT does splitting the exercises save over the two years?","d":"","o":["$9,574","$17,734","$19,148","$36,882"],"a":2,"cite":"IRC §55(a); IRC §56(b)(3); Form 6251 instructions","rat":"Exercising all in 2026: AMTI = $400,000; tentative tax $81,882; AMT $36,882.","ex":["This is one year's AMT under the split, not the total saving.","Exercising all in 2026: AMTI = $400,000; tentative tax $81,882; AMT $36,882. Splitting: AMTI = $300,000 each year; AMT $9,574 per year, $19,148 in total. Saving = $36,882 - $19,148 = $17,734.","This is the total AMT if the exercises are split, not the saving.","This is the AMT if all options are exercised in 2026, not the saving."],"wt":["trap","","trap","trap"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Spreading incentive stock option exercises keeps AMTI in the 26% band and lowers AMT because the exemption applies to each year.","from":"2026-01-01","calc":1,"steps":["All in 2026: AMTI 400,000 less 90,100 = $309,900; 0.26 x 244,500 + 0.28 x $65,400 = $81,882; less regular tax 45,000 = $36,882","Split: AMTI 300,000 less 90,100 = $209,900; x 26% = $54,574; less 45,000 = $9,574 per year; two years $19,148","Saving = $36,882 - $19,148 = $17,734"]}}],"3":[{"i":"TCP-I-A-0008","t":"Owen and Kim Tran's daughter, age 15 and a dependent, has $10,000 of interest income in 2026 and no earned income. Assume her standard deduction is $1,350, the first $2,700 of unearned income is not subject to the parents' rate (the $1,350 not covered by the standard deduction is taxed at her 10% rate), and her parents' marginal rate is 32%. What is her 2026 federal income tax?","mc":{"s":"Owen and Kim Tran's daughter, age 15 and a dependent, has $10,000 of interest income in 2026 and no earned income. Assume her standard deduction is $1,350, the first $2,700 of unearned income is not subject to the parents' rate (the $1,350 not covered by the standard deduction is taxed at her 10% rate), and her parents' marginal rate is 32%. What is her 2026 federal income tax?","d":"","o":["$2,336","$2,471","$2,768","$3,200"],"a":2,"cite":"IRC §1(g); Form 8615 instructions","rat":"Net unearned income = $10,000 - $2,700 = $7,300, taxed at 32% = $2,336.","ex":["Omits the tax at the child's own 10% rate on the first slice of taxable income.","Net unearned income = $10,000 - $2,700 = $7,300, taxed at 32% = $2,336. The remaining taxable income ($2,700 - $1,350 = $1,350) is taxed at 10% = $135. Total $2,471.","Taxes all taxable income after the standard deduction at the parents' rate. The first band of unearned income is taxed at the child's rate.","Taxes all unearned income at the parents' rate and ignores both the standard deduction and the child's own-rate slice."],"wt":["calc","","concept","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Under the kiddie tax, net unearned income above the threshold is taxed at the parents' rate; the rest of taxable income is taxed at the child's rates.","from":"2026-01-01","calc":1,"steps":["Net unearned income = 10,000 - 2,700 = $7,300; x 32% = $2,336","Other taxable income = (10,000 - 1,350) - $7,300 = $1,350; x 10% = $135","Total = $2,471"]}},{"i":"TCP-I-A-0009","t":"Hana Mori, who is in the 35% bracket, receives $12,000 a year of ordinary interest from bonds and considers giving the bonds to her son, age 12, who has no other income. Assume the son's standard deduction is $1,350, the first $2,700 of his unearned income is not taxed at the parent's rate, and the $1,350 band not covered by the standard deduction is taxed at 10%. Ignoring state tax and the gift tax, what annual federal income tax saving results from the transfer?","mc":{"s":"Hana Mori, who is in the 35% bracket, receives $12,000 a year of ordinary interest from bonds and considers giving the bonds to her son, age 12, who has no other income. Assume the son's standard deduction is $1,350, the first $2,700 of his unearned income is not taxed at the parent's rate, and the $1,350 band not covered by the standard deduction is taxed at 10%. Ignoring state tax and the gift tax, what annual federal income tax saving results from the transfer?","d":"","o":["$810","$2,662","$3,390","$4,200"],"a":1,"cite":"IRC §1(g); Form 8615 instructions","rat":"Hana now pays $12,000 x 35% = $4,200.","ex":["Hana now pays $12,000 x 35% = $4,200. After the gift, the son pays 35% on $9,300 of net unearned income ($3,255) plus 10% on $1,350 ($135), or $3,390. Saving = $810.","Assumes all of the son's taxable income after the standard deduction is taxed at 10%, which overstates the saving.","This is the son's tax after the transfer, not the saving.","Treats the son's tax as zero, as if the income escaped tax. Above the threshold the kiddie tax applies the parent's rate."],"wt":["","calc","trap","concept"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Shifting unearned income to a child saves tax only on the portion below the kiddie tax threshold; income above it is still taxed at the parent's rate.","from":"2026-01-01","calc":1,"steps":["Tax if Hana keeps the bonds = 12,000 x 35% = $4,200","Tax on son = (12,000 - 2,700) x 35% + (2,700 - 1,350) x 10% = $3,390","Saving = $810"]}}],"4":[{"i":"TCP-I-A-0010","t":"Dara Klein, a cash-basis attorney, expects her marginal federal rate to fall from 35% in 2026 to 24% in 2027. She can delay billing $40,000 of fees for December work until January, and she can pay $25,000 of deductible business expenses in December 2026 that she would otherwise pay in January 2027. Ignoring the time value of money and state tax, what federal tax saving results if she takes both actions?","mc":{"s":"Dara Klein, a cash-basis attorney, expects her marginal federal rate to fall from 35% in 2026 to 24% in 2027. She can delay billing $40,000 of fees for December work until January, and she can pay $25,000 of deductible business expenses in December 2026 that she would otherwise pay in January 2027. Ignoring the time value of money and state tax, what federal tax saving results if she takes both actions?","d":"","o":["$1,650","$2,750","$4,400","$7,150"],"a":4,"cite":"IRC §451; IRC §461(a); Reg. §1.451-2","rat":"Deferring $40,000 of income moves it from the 35% year to the 24% year, saving $4,400.","ex":["Subtracts the deduction benefit. Accelerating a deduction into the higher-rate year adds to the saving.","Counts only the accelerated expenses and omits the income deferral.","Counts only the income deferral and omits the accelerated deduction.","Deferring $40,000 of income moves it from the 35% year to the 24% year, saving $4,400. Paying the expenses in 2026 puts the deduction in the 35% year instead of the 24% year, saving $2,750. Total $7,150."],"wt":["concept","calc","calc",""],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"When rates will fall, defer income and accelerate deductions; each dollar shifted saves the rate difference.","from":"2026-01-01","calc":1,"steps":["Income deferral: 40,000 x (35% - 24%) = $4,400","Deduction acceleration: 25,000 x (35% - 24%) = $2,750","Total = $7,150"]}},{"i":"TCP-I-A-0011","t":"Jun Takeda, a cash-basis freelance designer, finished a client project on December 28, 2026. The client pays within a few days of receiving an invoice. Jun wants the income taxed in 2027. Which action successfully defers the income to 2027?","mc":{"s":"Jun Takeda, a cash-basis freelance designer, finished a client project on December 28, 2026. The client pays within a few days of receiving an invoice. Jun wants the income taxed in 2027. Which action successfully defers the income to 2027?","d":"","o":["Jun picks up the client's check on December 30 and does not deposit it until January 4","Jun sends the invoice on January 4, 2027, and the client pays after that date","Jun tells the client to leave the check in an unlocked drawer at the client's office, where Jun can collect it at any time","Jun asks the client to transfer the payment to Jun's bank account on December 31 and does not look at the account until January"],"a":2,"cite":"IRC §451(a); Reg. §1.451-1(a); Reg. §1.451-2(a)","rat":"A cash-basis taxpayer reports income when received or constructively received.","ex":["Receipt of a check in 2026 is receipt of income in 2026. Delaying the deposit does not delay income.","A cash-basis taxpayer reports income when received or constructively received. Payment that has not been offered or made available in 2026 is not income in 2026.","Payment that is set apart and available without restriction is constructively received, so it is 2026 income.","The funds are credited to Jun's account in 2026. Not checking the balance does not defer the income."],"wt":["trap","","concept","trap"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A cash-basis taxpayer may delay billing, but income that is paid, credited, or made available without restriction in the year is taxed in that year.","from":"2026-01-01"}},{"i":"TCP-I-A-0027","t":"Ike Barlow bought stock on January 10, 2026, and by mid-December 2026 it has an unrealized gain of $30,000. His ordinary rate is 35% and his long-term capital gains rate is 15%. He is deciding whether to sell on December 15, 2026 or on January 12, 2027 and expects the value to be unchanged. Ignoring the net investment income tax and state tax, how much federal tax does waiting until January 12 save?","mc":{"s":"Ike Barlow bought stock on January 10, 2026, and by mid-December 2026 it has an unrealized gain of $30,000. His ordinary rate is 35% and his long-term capital gains rate is 15%. He is deciding whether to sell on December 15, 2026 or on January 12, 2027 and expects the value to be unchanged. Ignoring the net investment income tax and state tax, how much federal tax does waiting until January 12 save?","d":"","o":["$4,500","$6,000","$10,500","$15,000"],"a":2,"cite":"IRC §1222; IRC §1(h); Pub 550","rat":"Selling in December is a short-term sale taxed at ordinary rates: $10,500.","ex":["This is the tax on the long-term sale, not the saving.","Selling in December is a short-term sale taxed at ordinary rates: $10,500. Selling on January 12, 2027 is after more than one year, so the gain is long-term at 15%: $4,500. The saving is $6,000.","This is the tax on the short-term sale, not the saving.","Adds the two rates instead of subtracting them."],"wt":["trap","","trap","calc"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A capital asset held more than one year qualifies for long-term rates; waiting a few days past the anniversary can change the rate.","from":"2026-01-01","calc":1,"steps":["Short-term tax = 30,000 x 35% = $10,500","Long-term tax = 30,000 x 15% = $4,500","Saving = $6,000"]}},{"i":"TCP-I-A-0033","t":"Tomas Ruiz, single, has realized $30,000 of long-term capital gain in 2026 and has no other capital transactions. On December 10 he holds Stock X, bought seven months earlier, with a $15,000 unrealized loss. Assume net long-term capital gain is taxed at 15%, ordinary income at 32%, and the net investment income tax does not apply. He considers three plans. Plan 1: sell Stock X on December 10 and buy the same shares back on December 20. Plan 2: sell Stock X on December 10 and buy the same shares back on January 15, 2027. Plan 3: keep Stock X. Which plan gives the largest 2026 federal tax reduction, and by how much?","mc":{"s":"Tomas Ruiz, single, has realized $30,000 of long-term capital gain in 2026 and has no other capital transactions. On December 10 he holds Stock X, bought seven months earlier, with a $15,000 unrealized loss. Assume net long-term capital gain is taxed at 15%, ordinary income at 32%, and the net investment income tax does not apply. He considers three plans. Plan 1: sell Stock X on December 10 and buy the same shares back on December 20. Plan 2: sell Stock X on December 10 and buy the same shares back on January 15, 2027. Plan 3: keep Stock X. Which plan gives the largest 2026 federal tax reduction, and by how much?","d":"","o":["Plan 1, because the loss is realized in 2026 and reduces tax by $2,250","Plan 2, because the short-term loss is deducted at 32% and reduces tax by $4,800","Plans 1 and 2 give the same $2,250 reduction, because the repurchase date does not affect the loss","Plan 2, because the loss is realized in 2026 and reduces tax by $2,250"],"a":4,"cite":"IRC §1091(a); IRC §1222; IRC §1211(b)","rat":"January 15 is 36 days after the sale, outside the 30-day wash sale period, so the loss counts in 2026.","ex":["Buying the same shares back within 30 days after the sale is a wash sale, so the $15,000 loss is disallowed and added to the basis of the new shares. Plan 1 gives no 2026 reduction.","The short-term loss is first netted against long-term gain, so it saves tax at the 15% long-term rate. It is not deducted at the ordinary rate because it is absorbed by gain.","The repurchase date decides the result. A repurchase within 30 days before or after the sale makes it a wash sale and defers the loss.","January 15 is 36 days after the sale, outside the 30-day wash sale period, so the loss counts in 2026. The $15,000 short-term loss nets against the $30,000 long-term gain, leaving $15,000 of long-term gain: tax falls from $4,500 to $2,250, a reduction of $2,250."],"wt":["concept","trap","concept",""],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"A loss on a sale of stock is disallowed if substantially identical stock is bought within 30 days before or after the sale; an allowed short-term loss first offsets long-term gain in the netting.","from":"2026-01-01","calc":1,"steps":["Wash sale window: December 10 plus 30 days ends January 9, so January 15 is outside it (36 days)","Plan 2: net long-term gain = 30,000 - 15,000 = 15,000, tax = 15,000 x 15% = 2,250 (versus 30,000 x 15% = 4,500)","Reduction = 4,500 - 2,250 = 2,250; Plan 1 loss is disallowed, so no reduction"]}},{"i":"TCP-I-A-0034","t":"Wendy Park, single, is a sole proprietor with 2026 net profit of $180,000 from a business that is not a specified service business. Her taxable income is below the level at which the wage and property limits apply, so her qualified business income deduction equals 20% of qualified business income, and the taxable income limit does not restrict it. Qualified business income is reduced by any deductible retirement plan contribution. Assume her marginal rate is 24% throughout and all of a $30,000 SEP-IRA contribution is deductible. By how much does the SEP-IRA contribution reduce her 2026 federal income tax?","mc":{"s":"Wendy Park, single, is a sole proprietor with 2026 net profit of $180,000 from a business that is not a specified service business. Her taxable income is below the level at which the wage and property limits apply, so her qualified business income deduction equals 20% of qualified business income, and the taxable income limit does not restrict it. Qualified business income is reduced by any deductible retirement plan contribution. Assume her marginal rate is 24% throughout and all of a $30,000 SEP-IRA contribution is deductible. By how much does the SEP-IRA contribution reduce her 2026 federal income tax?","d":"","o":["$1,440","$5,760","$6,000","$7,200"],"a":2,"cite":"IRC §199A(b)(2); IRC §199A(c)(1); Reg. §1.199A-3(b)(1)(iii); IRC §404(h)","rat":"The contribution lowers AGI and taxable income by $30,000 but also lowers qualified business income by $30,000, which cuts the 20% deduction by $6,000.","ex":["Computes only the effect of the lower qualified business income deduction ($6,000 x 24%). The contribution itself is also deducted.","The contribution lowers AGI and taxable income by $30,000 but also lowers qualified business income by $30,000, which cuts the 20% deduction by $6,000. Taxable income falls by a net $24,000, so tax falls by $24,000 x 24% = $5,760.","This is the amount of qualified business income deduction lost, $6,000, not a tax amount. The reduction is measured in tax, at her rate.","Ignores that the deductible contribution also reduces qualified business income and the 20% deduction. Tax falls by less than $30,000 x 24%."],"wt":["trap","","calc","trap"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"A deductible retirement contribution by a self-employed owner reduces qualified business income, so the net taxable income reduction is 80% of the contribution.","from":"2026-07-01","calc":1,"steps":["Contribution reduces AGI and taxable income by 30,000","Qualified business income falls 30,000, so the deduction falls 20% x 30,000 = 6,000","Net taxable income reduction = 30,000 - 6,000 = 24,000; tax reduction = 24,000 x 24% = 5,760"]}}],"5":[{"i":"TCP-I-A-0012","t":"Tom Reyes, age 43, has family coverage under a qualifying high-deductible health plan and no other health coverage. He contributes the maximum allowed to a health savings account through payroll deductions under his employer's cafeteria plan. Assume the 2026 family contribution limit is $8,750, his federal marginal rate is 24%, employee-side Social Security and Medicare tax is 7.65%, and state tax is ignored. What is his projected 2026 federal income tax and payroll tax saving?","mc":{"s":"Tom Reyes, age 43, has family coverage under a qualifying high-deductible health plan and no other health coverage. He contributes the maximum allowed to a health savings account through payroll deductions under his employer's cafeteria plan. Assume the 2026 family contribution limit is $8,750, his federal marginal rate is 24%, employee-side Social Security and Medicare tax is 7.65%, and state tax is ignored. What is his projected 2026 federal income tax and payroll tax saving?","d":"","o":["$669","$2,100","$2,769","$3,086"],"a":3,"cite":"IRC §223(b); IRC §125; IRC §3121(a)(2)","rat":"The contribution reduces income subject to federal tax and, because it runs through the cafeteria plan, FICA wages too.","ex":["Counts only the payroll tax and omits the income tax saving.","Counts only income tax. Payroll contributions through a cafeteria plan also reduce FICA wages.","The contribution reduces income subject to federal tax and, because it runs through the cafeteria plan, FICA wages too. $8,750 x (24% + 7.65%) = $2,769.","Adds the $1,000 catch-up contribution, which is available only from age 55."],"wt":["concept","concept","","limit"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"HSA contributions made through a cafeteria plan avoid both income tax and FICA; the catch-up amount requires age 55 or older.","from":"2026-01-01","calc":1,"steps":["Maximum contribution = 8,750; no catch-up because Tom is under 55","Saving = 8,750 x (0.24 + 0.0765) = $2,769"]}},{"i":"TCP-I-A-0013","t":"Mia Zhang, age 37, has family coverage under a qualifying high-deductible health plan through her employer and has no other coverage of her own. Her spouse's employer offers a general-purpose health flexible spending account, and the spouse enrolls in it for 2026 with reimbursement available for the whole family. Which statement about Mia's health savings account for 2026 is correct?","mc":{"s":"Mia Zhang, age 37, has family coverage under a qualifying high-deductible health plan through her employer and has no other coverage of her own. Her spouse's employer offers a general-purpose health flexible spending account, and the spouse enrolls in it for 2026 with reimbursement available for the whole family. Which statement about Mia's health savings account for 2026 is correct?","d":"","o":["Mia may not make HSA contributions because the spouse's general-purpose FSA can reimburse her expenses","Mia may contribute up to the full family limit because the FSA belongs to her spouse and not to her","Mia may contribute the family limit reduced by the amount of the spouse's FSA election","Mia may contribute up to half of the family limit because only her spouse participates in the FSA plan"],"a":1,"cite":"IRC §223(c)(1); IRC §223(c)(2); Notice 2004-50","rat":"Coverage under a general-purpose health FSA is disqualifying other coverage, even when the FSA belongs to a spouse and covers the family.","ex":["Coverage under a general-purpose health FSA is disqualifying other coverage, even when the FSA belongs to a spouse and covers the family.","Ownership of the FSA does not matter. Eligibility turns on whether Mia herself can be reimbursed for medical expenses.","There is no proportional reduction for FSA elections. The FSA coverage either disqualifies her or it does not.","No half-limit rule exists for this situation. A general-purpose FSA that covers her disqualifies the contribution entirely."],"wt":["","trap","concept","concept"],"tags":{"area":"I","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A general-purpose health FSA (including a spouse's that covers you) disqualifies HSA contributions; a limited-purpose FSA does not.","from":"2026-01-01"}},{"i":"TCP-I-A-0026","t":"Carla Ng, a single parent, elects to contribute the maximum to her employer's dependent care flexible spending account for 2026 and will use it fully for qualifying daycare costs. Assume the 2026 limit is $7,500 for her, her federal marginal rate is 24%, and payroll tax is 7.65%. What is her projected federal income and payroll tax saving?","mc":{"s":"Carla Ng, a single parent, elects to contribute the maximum to her employer's dependent care flexible spending account for 2026 and will use it fully for qualifying daycare costs. Assume the 2026 limit is $7,500 for her, her federal marginal rate is 24%, and payroll tax is 7.65%. What is her projected federal income and payroll tax saving?","d":"","o":["$574","$1,583","$1,800","$2,374"],"a":4,"cite":"IRC §129(a); IRC §129(a)(2)(A); Form 2441 instructions","rat":"Salary reductions to a dependent care account escape both income tax and FICA: $7,500 x (24% + 7.65%) = $2,374.","ex":["Counts only payroll tax.","Uses the former $5,000 limit instead of the amount given for 2026.","Counts only income tax.","Salary reductions to a dependent care account escape both income tax and FICA: $7,500 x (24% + 7.65%) = $2,374."],"wt":["concept","limit","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Dependent care FSA contributions reduce wages for income tax and FICA up to the annual limit.","from":"2026-07-01","calc":1,"steps":["Saving = 7,500 x (0.24 + 0.0765) = $2,374"]}},{"i":"TCP-I-A-0035","t":"Marta Keller, age 40, is single with a child and has family coverage under a qualifying high-deductible health plan, so her 2026 HSA limit is $8,750. She expects $6,000 of qualified medical expenses in 2026. Her AGI before any HSA contribution is $80,000 and she is in the 22% bracket. Her other itemizable deductions total $9,000, well below the $16,100 standard deduction. She can (1) pay the $6,000 with after-tax dollars, or (2) contribute $6,000 to an HSA through her employer's cafeteria plan by salary reduction and pay the expenses from the HSA. Assume employee FICA is 7.65% on her wages, she is below the Social Security wage base, and medical expenses are deductible only above 7.5% of AGI. How much lower is her combined 2026 federal income tax and employee FICA under choice (2) than under choice (1)?","mc":{"s":"Marta Keller, age 40, is single with a child and has family coverage under a qualifying high-deductible health plan, so her 2026 HSA limit is $8,750. She expects $6,000 of qualified medical expenses in 2026. Her AGI before any HSA contribution is $80,000 and she is in the 22% bracket. Her other itemizable deductions total $9,000, well below the $16,100 standard deduction. She can (1) pay the $6,000 with after-tax dollars, or (2) contribute $6,000 to an HSA through her employer's cafeteria plan by salary reduction and pay the expenses from the HSA. Assume employee FICA is 7.65% on her wages, she is below the Social Security wage base, and medical expenses are deductible only above 7.5% of AGI. How much lower is her combined 2026 federal income tax and employee FICA under choice (2) than under choice (1)?","d":"","o":["$459","$1,320","$1,779","$2,238"],"a":3,"cite":"IRC §223(a); IRC §125(d); IRC §3121(a)(2); IRC §213(a)","rat":"Under choice (1) no itemized medical deduction arises: the 7.5% floor is $6,000, and her itemized total is below the standard deduction anyway.","ex":["Counts only FICA. The salary reduction also removes the $6,000 from taxable income and saves income tax at 22%.","Counts only income tax. Contributions made by salary reduction through a cafeteria plan also avoid employee FICA.","Under choice (1) no itemized medical deduction arises: the 7.5% floor is $6,000, and her itemized total is below the standard deduction anyway. Under choice (2) the salary reduction avoids both income tax (22%) and FICA (7.65%): $6,000 x 29.65% = $1,779.","Uses 15.3%, which is the combined employer and employee FICA rate. Only the employee's 7.65% is her cost."],"wt":["trap","trap","","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"A medical expense paid through a pre-tax HSA salary reduction saves income tax and FICA, while the itemized deduction gives nothing if it falls below the 7.5% floor or the standard deduction.","from":"2026-01-01","calc":1,"steps":["Choice 1: 7.5% x 80,000 = 6,000 floor, so the medical deduction is 0; itemized 9,000 < 16,100, so no tax benefit","Choice 2: salary reduction of 6,000 avoids income tax 6,000 x 22% = 1,320 and FICA 6,000 x 7.65% = 459","Difference = 1,320 + 459 = 1,779"]}}],"6":[{"i":"TCP-I-A-0014","t":"Ruth and Paul Ochoa file jointly for 2026 with AGI of $200,000 and a 22% marginal rate. The standard deduction is $32,200. Their possible itemized deductions are qualified mortgage interest of $15,000, state income tax of $11,000, real property tax of $8,000, and cash gifts to their church of $6,000. Assume the limitation on state and local taxes is $40,400 for them, and that itemized charitable gifts are deductible only to the extent they exceed 0.5% of AGI. By how much does itemizing reduce their 2026 federal income tax compared with claiming the standard deduction?","mc":{"s":"Ruth and Paul Ochoa file jointly for 2026 with AGI of $200,000 and a 22% marginal rate. The standard deduction is $32,200. Their possible itemized deductions are qualified mortgage interest of $15,000, state income tax of $11,000, real property tax of $8,000, and cash gifts to their church of $6,000. Assume the limitation on state and local taxes is $40,400 for them, and that itemized charitable gifts are deductible only to the extent they exceed 0.5% of AGI. By how much does itemizing reduce their 2026 federal income tax compared with claiming the standard deduction?","d":"","o":["$1,496","$1,716","$6,800","$8,580"],"a":1,"cite":"IRC §63(d); IRC §164(b)(6); IRC §170(b)(1)(I)","rat":"Charitable gifts are reduced by 0.5% x $200,000 = $1,000, leaving $5,000.","ex":["Charitable gifts are reduced by 0.5% x $200,000 = $1,000, leaving $5,000. Itemized deductions = $39,000, which exceeds the standard deduction by $6,800. Tax saving = $6,800 x 22% = $1,496.","Ignores the 0.5% of AGI floor on charitable gifts.","Reports the extra deduction instead of the tax it saves.","Applies the rate to the whole itemized total instead of only the excess over the standard deduction they would receive anyway."],"wt":["","limit","trap","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Itemizing helps only by the excess of allowed itemized deductions over the standard deduction, multiplied by the marginal rate.","from":"2026-07-01","calc":1,"steps":["Charitable deduction = 6,000 - 0.5% x 200,000 = $5,000","Itemized total = 15,000 + 19,000 (state and local taxes, under the limit) + $5,000 = $39,000","Excess over standard deduction = $39,000 - 32,200 = $6,800","Saving = $6,800 x 22% = $1,496"]}},{"i":"TCP-I-A-0015","t":"Amir and Sana Haddad file jointly, have AGI of $150,000 in both 2026 and 2027, and a 22% marginal rate. Each year they have $22,000 of mortgage interest and state and local taxes combined, and they normally give $8,000 in cash to charity. The standard deduction is $32,200 each year, and itemized charitable gifts are deductible only to the extent they exceed 0.5% of AGI. They consider giving $16,000 to a donor-advised fund in 2026 and nothing in 2027, claiming the larger deduction in whichever year is better. What is the two-year federal tax saving from bunching?","mc":{"s":"Amir and Sana Haddad file jointly, have AGI of $150,000 in both 2026 and 2027, and a 22% marginal rate. Each year they have $22,000 of mortgage interest and state and local taxes combined, and they normally give $8,000 in cash to charity. The standard deduction is $32,200 each year, and itemized charitable gifts are deductible only to the extent they exceed 0.5% of AGI. They consider giving $16,000 to a donor-advised fund in 2026 and nothing in 2027, claiming the larger deduction in whichever year is better. What is the two-year federal tax saving from bunching?","d":"","o":["$1,111","$1,276","$3,520","$5,050"],"a":1,"cite":"IRC §63(d); IRC §170(b)(1)(I); IRC §170(a)(1)","rat":"Without bunching each year's itemized total ($29,250) is below the standard deduction, so they deduct $64,400 over two years.","ex":["Without bunching each year's itemized total ($29,250) is below the standard deduction, so they deduct $64,400 over two years. With bunching, 2026 itemized deductions are $37,250 and 2027 uses the standard deduction of $32,200, for $69,450. The extra $5,050 x 22% = $1,111.","Ignores the 0.5% of AGI floor on the bunched gift.","Applies the rate to the whole gift. Without bunching the standard deduction already gives them part of that benefit, so only the added deduction counts.","Reports the added deductions instead of the tax saving."],"wt":["","limit","concept","trap"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Bunching pays when itemized deductions alternate above and below the standard deduction; the floor applies once to the bunched gift.","from":"2026-07-01","calc":1,"steps":["No bunching: max($29,250, 32,200) = 32,200 each year, total $64,400","2026 bunched itemized = 22,000 + (16,000 - $750) = $37,250; 2027 = standard 32,200; total $69,450","Extra deductions = $5,050; saving = x 22% = $1,111"]}},{"i":"TCP-I-A-0032","t":"Ravi and Meera Kapoor file jointly and itemize deductions. Assume that for 2026 the deduction for state and local taxes is capped at $40,400, reduced by 30% of modified AGI above $505,000, and never reduced below $10,000. They paid $48,000 of state income and property taxes. Their modified AGI is $565,000 before any additional retirement deferral. Ravi can defer another $20,000 of salary into his employer's traditional 401(k) plan, which lowers modified AGI dollar for dollar. Assume their marginal rate is 35% throughout, they itemize either way, and no other item changes. By how much does the additional deferral reduce their 2026 federal income tax?","mc":{"s":"Ravi and Meera Kapoor file jointly and itemize deductions. Assume that for 2026 the deduction for state and local taxes is capped at $40,400, reduced by 30% of modified AGI above $505,000, and never reduced below $10,000. They paid $48,000 of state income and property taxes. Their modified AGI is $565,000 before any additional retirement deferral. Ravi can defer another $20,000 of salary into his employer's traditional 401(k) plan, which lowers modified AGI dollar for dollar. Assume their marginal rate is 35% throughout, they itemize either way, and no other item changes. By how much does the additional deferral reduce their 2026 federal income tax?","d":"","o":["$2,100","$7,000","$9,100","$14,000"],"a":3,"cite":"IRC §164(b)(7); IRC §402(g); P.L. 119-21 §70120","rat":"The deferral saves $20,000 x 35% = $7,000 directly.","ex":["Counts only the extra state and local tax deduction ($6,000 x 35%). The $20,000 deferral also reduces taxable income directly.","Counts only the salary deferral. It misses the larger state and local tax deduction that results from a lower modified AGI.","The deferral saves $20,000 x 35% = $7,000 directly. It also lowers modified AGI to $545,000, so the state and local tax cap rises from $22,400 to $28,400 and the deduction rises by $6,000, saving another $2,100. Total $9,100.","Assumes the SALT deduction rises by the full $20,000 of deferral. The cap rises by only 30% of the reduction in modified AGI, or $6,000."],"wt":["trap","trap","","calc"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A high-income taxpayer's state and local tax cap is reduced by 30% of modified AGI over the threshold, so an action that lowers modified AGI gives a second deduction benefit.","from":"2026-07-01","calc":1,"steps":["Cap before deferral = 40,400 - 30% x (565,000 - 505,000) = 22,400; deduction = 22,400 (paid 48,000)","Cap after deferral = 40,400 - 30% x (545,000 - 505,000) = 28,400; deduction = 28,400","Direct saving = 20,000 x 35% = 7,000; SALT saving = (28,400 - 22,400) x 35% = 2,100","Total = 7,000 + 2,100 = 9,100"]}},{"i":"TCP-I-A-0036","t":"Ed Rossi, age 74, single, must take a $30,000 required minimum distribution from his traditional IRA in 2026 and wants to give $10,000 to his church. He has a $165,000 pension, and $12,000 of other itemizable deductions. Assume his standard deduction is $18,150, his income is high enough that any extra deduction for taxpayers age 65 or older is fully phased out, and he is in the 24% bracket at all the relevant income levels. Assume that charitable gifts of cash are deductible only above 0.5% of AGI. Option 1: take the full $30,000 distribution and give $10,000 of cash to the church. Option 2: direct the IRA custodian to send $10,000 to the church as a qualified charitable distribution and take the other $20,000 as his required distribution. Ed uses the larger of itemized and standard deductions each way. How much lower is his 2026 federal income tax under Option 2?","mc":{"s":"Ed Rossi, age 74, single, must take a $30,000 required minimum distribution from his traditional IRA in 2026 and wants to give $10,000 to his church. He has a $165,000 pension, and $12,000 of other itemizable deductions. Assume his standard deduction is $18,150, his income is high enough that any extra deduction for taxpayers age 65 or older is fully phased out, and he is in the 24% bracket at all the relevant income levels. Assume that charitable gifts of cash are deductible only above 0.5% of AGI. Option 1: take the full $30,000 distribution and give $10,000 of cash to the church. Option 2: direct the IRA custodian to send $10,000 to the church as a qualified charitable distribution and take the other $20,000 as his required distribution. Ed uses the larger of itemized and standard deductions each way. How much lower is his 2026 federal income tax under Option 2?","d":"","o":["$1,476","$1,710","$2,400","$4,800"],"a":2,"cite":"IRC §408(d)(8); IRC §170(b)(1)(I); IRC §401(a)(9); P.L. 119-21 §70425","rat":"Option 1: AGI is $195,000, the gift is deductible only above the $975 floor, so itemized deductions are $12,000 + $9,025 = $21,025, above the standard deduction.","ex":["Deducts the full $10,000 gift in Option 1 and ignores the 0.5% of AGI floor. The floor removes $975 of the gift deduction.","Option 1: AGI is $195,000, the gift is deductible only above the $975 floor, so itemized deductions are $12,000 + $9,025 = $21,025, above the standard deduction. Option 2: AGI is $185,000 and itemized deductions of $12,000 are below the standard deduction, so he takes $18,150. Taxable income is $173,975 versus $166,850, a difference of $7,125, and tax is $1,710 lower.","Assumes the gift saves nothing under Option 1 and the exclusion saves the full $10,000 at 24%. In Option 1 he itemizes and gets a deduction for most of the gift.","Applies the rate to the $20,000 of distribution he still takes. The QCD keeps only the $10,000 given to the church out of income."],"wt":["calc","","trap","trap"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A qualified charitable distribution is excluded from gross income and counts toward the required distribution, and it beats a cash gift because the cash gift is subject to the AGI floor and to the choice of standard deduction.","from":"2026-07-01","calc":1,"steps":["Option 1: AGI = 165,000 + 30,000 = 195,000; deductible gift = 10,000 - 0.5% x 195,000 = 9,025; itemized = 12,000 + 9,025 = 21,025 (> 18,150)","Taxable income = 195,000 - 21,025 = 173,975","Option 2: AGI = 165,000 + 20,000 = 185,000; itemized 12,000 < 18,150, so standard deduction; taxable income = 185,000 - 18,150 = 166,850","Difference = 173,975 - 166,850 = 7,125; tax = 7,125 x 24% = 1,710"]}}],"7":[{"i":"TCP-I-A-0016","t":"Jenna Brandt, a single taxpayer, had 2025 AGI of $165,000 and total 2025 tax of $38,000. She expects her 2026 total tax to be $52,000. Her employer will withhold $10,000 for the year, spread evenly, and she wants to make four equal estimated payments that are just enough to avoid the underpayment penalty. What is each payment?","mc":{"s":"Jenna Brandt, a single taxpayer, had 2025 AGI of $165,000 and total 2025 tax of $38,000. She expects her 2026 total tax to be $52,000. Her employer will withhold $10,000 for the year, spread evenly, and she wants to make four equal estimated payments that are just enough to avoid the underpayment penalty. What is each payment?","d":"","o":["$7,000","$7,950","$9,200","$10,500"],"a":2,"cite":"IRC §6654(d)(1); IRC §6654(d)(1)(C); Form 2210 instructions","rat":"Her prior-year AGI exceeds $150,000, so the prior-year safe harbor is 110% of 2025 tax = $41,800.","ex":["Uses 100% of prior-year tax. With prior-year AGI above $150,000 the prior-year safe harbor is 110%.","Her prior-year AGI exceeds $150,000, so the prior-year safe harbor is 110% of 2025 tax = $41,800. The current-year safe harbor is 90% of $52,000 = $46,800. The smaller, $41,800, less withholding of $10,000 leaves $31,800, or $7,950 per installment.","Uses only the 90% current-year test. The smaller of the two safe harbors is enough to avoid the penalty.","Pays 100% of the expected current-year tax. That is more than the law requires."],"wt":["limit","","concept","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"To avoid the penalty pay the smaller of 90% of current-year tax or 100% (110% if prior AGI exceeds $150,000) of prior-year tax, less withholding.","from":"2026-01-01","calc":1,"steps":["90% of 2026 tax = $46,800; 110% of 2025 tax = $41,800","Required annual payment = $41,800","Less withholding 10,000 = $31,800; / 4 = $7,950"]}},{"i":"TCP-I-A-0017","t":"Andre Silva is a salaried employee with no other income. He made no estimated tax payments in 2026, and in early December he learns that his withholding will fall far short of the amount needed to avoid the underpayment penalty. His employer will still process payroll for the rest of December. Which action best reduces the penalty for the year?","mc":{"s":"Andre Silva is a salaried employee with no other income. He made no estimated tax payments in 2026, and in early December he learns that his withholding will fall far short of the amount needed to avoid the underpayment penalty. His employer will still process payroll for the rest of December. Which action best reduces the penalty for the year?","d":"","o":["Mail a single large estimated tax payment on December 31 to cover the full shortfall for the year","Submit a new Form W-4 asking the employer to increase withholding on remaining pay","Wait to file the return and pay the balance due by April 15 of the following year","File Form 4868 to extend the time to file the return, and pay the balance with it"],"a":2,"cite":"IRC §6654(g)(1); Form 2210 instructions; Pub 505","rat":"Withholding is treated as paid in equal installments on the due dates regardless of when it is actually withheld, so extra withholding late in the year cures earlier shortfalls.","ex":["An estimated payment counts only from the date it is paid. The earlier installments remain underpaid and still bear the penalty.","Withholding is treated as paid in equal installments on the due dates regardless of when it is actually withheld, so extra withholding late in the year cures earlier shortfalls.","The penalty is computed for each installment due date, so paying with the return does not remove the penalty already accrued.","An extension to file does not extend the time to pay, and the penalty is unaffected."],"wt":["trap","","concept","concept"],"tags":{"area":"I","group":"A","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Withholding is deemed paid evenly over the year, so late-year withholding increases can eliminate earlier installment shortfalls; estimated payments count when made.","from":"2026-01-01"}},{"i":"TCP-I-A-0018","t":"Padma Iyer, a U.S. citizen, had no federal income tax liability for 2025, a full 12-month tax year, because of a large business loss. In 2026 she earns substantial income and expects a total tax of $30,000. She had no withholding and made no estimated payments during 2026. Which statement about the underpayment of estimated tax penalty for 2026 is correct?","mc":{"s":"Padma Iyer, a U.S. citizen, had no federal income tax liability for 2025, a full 12-month tax year, because of a large business loss. In 2026 she earns substantial income and expects a total tax of $30,000. She had no withholding and made no estimated payments during 2026. Which statement about the underpayment of estimated tax penalty for 2026 is correct?","d":"","o":["A penalty applies to the entire $30,000 because she paid less than 90% of her 2026 tax liability","A penalty applies only to the installments due after she first receives the income","No penalty applies only if she pays at least half of the $30,000 by September 15","No penalty applies, because she owed no tax for 2025 and it was a full 12-month year"],"a":4,"cite":"IRC §6654(e)(2); Form 2210 instructions","rat":"A taxpayer who owed no tax for a 12-month prior year, and was a citizen or resident throughout it, has no estimated tax penalty for the current year.","ex":["The 90% test is only one way to avoid the penalty. An exception applies when the prior-year liability was zero.","That describes the annualized income installment method, which does not need to be used here because no penalty is imposed at all.","There is no half-of-tax test. The exception is automatic when the prior-year tax was zero.","A taxpayer who owed no tax for a 12-month prior year, and was a citizen or resident throughout it, has no estimated tax penalty for the current year."],"wt":["concept","trap","concept",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"No estimated tax penalty applies if the prior year was a 12-month year with zero tax liability and the taxpayer was a citizen or resident all year.","from":"2026-01-01"}}],"8":[{"i":"TCP-I-A-0019","t":"Grace Lindqvist, who is in the 35% bracket and pays 15% on long-term capital gains, wants to give $40,000 to her public charity. She owns stock worth $40,000 with a basis of $10,000 that she has held for three years. She could either (1) give the stock, or (2) sell it and give the after-tax proceeds in cash. Assume all deductions are fully allowed within the AGI limits and ignore state tax and the net investment income tax. How much larger is her net federal tax benefit (charitable deduction saving minus any capital gains tax) from the stock gift than from the cash gift?","mc":{"s":"Grace Lindqvist, who is in the 35% bracket and pays 15% on long-term capital gains, wants to give $40,000 to her public charity. She owns stock worth $40,000 with a basis of $10,000 that she has held for three years. She could either (1) give the stock, or (2) sell it and give the after-tax proceeds in cash. Assume all deductions are fully allowed within the AGI limits and ignore state tax and the net investment income tax. How much larger is her net federal tax benefit (charitable deduction saving minus any capital gains tax) from the stock gift than from the cash gift?","d":"","o":["$1,575","$4,500","$6,075","$14,000"],"a":3,"cite":"IRC §170(e)(1); IRC §170(b)(1)(C); Pub 526","rat":"Giving the stock avoids the $4,500 capital gains tax and yields a deduction of $40,000 x 35% = $14,000.","ex":["This is only the extra deduction value ($4,500 x 35%) from giving the full $40,000 instead of $35,500. It leaves out the $4,500 capital gains tax that selling triggers.","Counts only the capital gains tax avoided and ignores the larger charitable deduction.","Giving the stock avoids the $4,500 capital gains tax and yields a deduction of $40,000 x 35% = $14,000. Selling first leaves $35,500 of cash to give, a deduction worth $12,425, and costs $4,500 of tax, for a net $7,925. The difference is $6,075.","Treats the whole deduction as the advantage. The cash gift also produces a deduction, so only the difference counts."],"wt":["calc","calc","","concept"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Donating long-term appreciated stock to a public charity avoids the gain and allows a deduction at fair market value; selling first loses both benefits.","from":"2026-01-01","calc":1,"steps":["Stock gift: deduction 40,000 x 35% = $14,000; no gain tax","Sale first: tax $4,500; cash gift $35,500 x 35% = $12,425; net $7,925","Difference = $6,075"]}},{"i":"TCP-I-A-0020","t":"Lucas Wren plans to give his public charity stock worth $18,000 on which his basis is $30,000; he has held it for two years. In the same year he has other long-term capital gains taxed at 15%, and his ordinary rate is 32%. He could either give the stock or sell it and give the $18,000 of proceeds in cash. Assume the charitable deduction is the same in both cases and is fully allowed. What additional federal tax saving results from selling first?","mc":{"s":"Lucas Wren plans to give his public charity stock worth $18,000 on which his basis is $30,000; he has held it for two years. In the same year he has other long-term capital gains taxed at 15%, and his ordinary rate is 32%. He could either give the stock or sell it and give the $18,000 of proceeds in cash. Assume the charitable deduction is the same in both cases and is fully allowed. What additional federal tax saving results from selling first?","d":"","o":["$1,800","$3,840","$5,760","$12,000"],"a":1,"cite":"IRC §170(e)(1); IRC §1211(b); IRC §165(c)","rat":"Giving loss stock produces a deduction limited to fair market value and the built-in loss is wasted.","ex":["Giving loss stock produces a deduction limited to fair market value and the built-in loss is wasted. Selling first recognizes a $12,000 long-term capital loss, which offsets gains taxed at 15%: $1,800.","Applies the ordinary rate to the loss. The loss offsets long-term gains taxed at 15%.","Values the charitable deduction, which is the same either way.","Reports the loss amount rather than the tax it saves."],"wt":["","concept","trap","trap"],"tags":{"area":"I","group":"A","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Loss property should be sold so the loss is recognized, then the cash given; a gift of loss property wastes the loss.","from":"2026-01-01","calc":1,"steps":["Recognized loss = 30,000 - 18,000 = $12,000","Tax saved = $12,000 x 15% = $1,800"]}},{"i":"TCP-I-A-0021","t":"Elisa Rinaldi, in the 35% bracket, owns a painting worth $60,000 with a basis of $8,000 that she has held for six years. She plans to give it to a public charity. Assume the deduction is fully allowed within the AGI limits. By how much does her tax saving increase if the charity is a museum that will display the painting than if it is a charity that will sell it at auction to fund scholarships?","mc":{"s":"Elisa Rinaldi, in the 35% bracket, owns a painting worth $60,000 with a basis of $8,000 that she has held for six years. She plans to give it to a public charity. Assume the deduction is fully allowed within the AGI limits. By how much does her tax saving increase if the charity is a museum that will display the painting than if it is a charity that will sell it at auction to fund scholarships?","d":"","o":["$2,800","$9,100","$12,480","$18,200"],"a":4,"cite":"IRC §170(e)(1)(B)(i); Reg. §1.170A-4(b)(3); Pub 526","rat":"A gift of tangible personal property put to a related use is deducted at fair market value; if the charity sells it (unrelated use), the deduction is limited to basis.","ex":["This is the value of the basis-only deduction, the amount she gets in both cases.","Halves the tax saving.","Applies a 24% rate instead of the 35% rate that is given.","A gift of tangible personal property put to a related use is deducted at fair market value; if the charity sells it (unrelated use), the deduction is limited to basis. The difference in deduction is $60,000 - $8,000 = $52,000, and x 35% = $18,200."],"wt":["trap","calc","limit",""],"tags":{"area":"I","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Tangible personal property given for an unrelated use is deducted at basis; for a related use it is deducted at fair market value.","from":"2026-01-01","calc":1,"steps":["Unrelated use: deduction = basis 8,000","Related use: deduction = fair market value 60,000","Increase = $52,000 x 35% = $18,200"]}}],"9":[{"i":"TCP-I-B-0001","t":"Gil Osei is a limited partner in a partnership that owns rental real estate. His share of the 2026 loss is $140,000. His outside basis is high enough to absorb the loss, and he has enough passive income that the passive loss rules do not limit it. His at-risk position includes $30,000 of cash he contributed, $20,000 of partnership recourse debt for which he is personally liable, $50,000 of his share of qualified nonrecourse financing from an unrelated commercial bank secured by the real estate, and $25,000 of his share of a nonrecourse loan from another partner. What amount of the 2026 loss survives the at-risk limitation?","mc":{"s":"Gil Osei is a limited partner in a partnership that owns rental real estate. His share of the 2026 loss is $140,000. His outside basis is high enough to absorb the loss, and he has enough passive income that the passive loss rules do not limit it. His at-risk position includes $30,000 of cash he contributed, $20,000 of partnership recourse debt for which he is personally liable, $50,000 of his share of qualified nonrecourse financing from an unrelated commercial bank secured by the real estate, and $25,000 of his share of a nonrecourse loan from another partner. What amount of the 2026 loss survives the at-risk limitation?","d":"","o":["$50,000","$75,000","$80,000","$100,000"],"a":4,"cite":"IRC §465(b)(1)-(6); Form 6198 instructions; Pub 925","rat":"Cash ($30,000), personally guaranteed debt ($20,000) and qualified nonrecourse financing on real estate ($50,000) are at risk: $100,000.","ex":["Leaves out qualified nonrecourse financing. For real estate, a partner's share of qualified nonrecourse financing counts as at risk.","Includes the loan from another partner but leaves out qualified nonrecourse financing.","Leaves out the recourse debt for which he is personally liable.","Cash ($30,000), personally guaranteed debt ($20,000) and qualified nonrecourse financing on real estate ($50,000) are at risk: $100,000. The nonrecourse loan from another partner is not qualified nonrecourse financing, so it is not at risk."],"wt":["concept","concept","concept",""],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"At-risk includes cash, contributed property, recourse debt and qualified nonrecourse financing on real estate, but not other nonrecourse debt or loans from interested persons.","from":"2026-01-01","calc":1,"steps":["At risk = 30,000 + 20,000 + 50,000 = $100,000","Loss allowed = lesser of 140,000 or $100,000 = $100,000"]}},{"i":"TCP-I-B-0002","t":"Sasha Ivers, a general partner who materially participates, began 2026 with an at-risk amount of $0 because prior losses used it up, and she has $15,000 of prior losses suspended by the at-risk rules. During 2026 she contributed $25,000 in cash to the partnership and her share of the partnership's income was $10,000. Assume the partnership has no 2026 loss and that her basis limit does not apply. What is her at-risk amount at the end of 2026 after the suspended losses are allowed?","mc":{"s":"Sasha Ivers, a general partner who materially participates, began 2026 with an at-risk amount of $0 because prior losses used it up, and she has $15,000 of prior losses suspended by the at-risk rules. During 2026 she contributed $25,000 in cash to the partnership and her share of the partnership's income was $10,000. Assume the partnership has no 2026 loss and that her basis limit does not apply. What is her at-risk amount at the end of 2026 after the suspended losses are allowed?","d":"","o":["$5,000","$10,000","$15,000","$20,000"],"a":4,"cite":"IRC §465(a)(2); IRC §465(b); Form 6198 instructions","rat":"Her at-risk amount before deducting suspended losses is $25,000 + $10,000 = $35,000.","ex":["Subtracts the suspended losses twice.","Leaves out the year's income, which increases the at-risk amount.","Reports the suspended losses instead of the ending at-risk amount.","Her at-risk amount before deducting suspended losses is $25,000 + $10,000 = $35,000. That exceeds the $15,000 of suspended losses, so all are allowed and the at-risk amount falls to $20,000."],"wt":["calc","calc","trap",""],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Contributions and income increase the at-risk amount; losses previously suspended are allowed to the extent of the amount at risk and reduce it.","from":"2026-01-01","calc":1,"steps":["Amount at risk before losses = 0 + 25,000 + 10,000 = $35,000","Suspended losses allowed = 15,000; ending amount = $20,000"]}},{"i":"TCP-I-B-0008","t":"Nisha Shah is a limited partner (a passive activity for her). Her share of the partnership's 2026 loss is $80,000. Her outside basis at year end before the loss is $60,000, her at-risk amount is $45,000, and she has $20,000 of passive income from another partnership. She has no other passive items. How much of the loss is suspended because of the passive activity rules, after the basis and at-risk limits have been applied?","mc":{"s":"Nisha Shah is a limited partner (a passive activity for her). Her share of the partnership's 2026 loss is $80,000. Her outside basis at year end before the loss is $60,000, her at-risk amount is $45,000, and she has $20,000 of passive income from another partnership. She has no other passive items. How much of the loss is suspended because of the passive activity rules, after the basis and at-risk limits have been applied?","d":"","o":["$15,000","$20,000","$25,000","$60,000"],"a":3,"cite":"IRC §704(d); IRC §465(a); IRC §469(a)","rat":"The limits apply in order: basis ($60,000), then at-risk ($45,000), then the passive activity rules.","ex":["This is the part suspended by the at-risk limit, not the passive activity limit.","This is the part suspended by the basis limit, not the passive activity limit.","The limits apply in order: basis ($60,000), then at-risk ($45,000), then the passive activity rules. After the first two, $45,000 remains, and the passive rules allow a deduction only against $20,000 of passive income. The amount suspended by the passive rules is $45,000 - $20,000 = $25,000.","Applies the passive limit to the entire loss and ignores the basis and at-risk limits applied first."],"wt":["trap","trap","","concept"],"tags":{"area":"I","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Partnership losses pass three limits in order: basis, at-risk, then passive activity; each disallowed piece is carried forward.","from":"2026-01-01","calc":1,"steps":["Suspended by basis = 80,000 - 60,000 = $20,000","Suspended by at-risk = 60,000 - 45,000 = $15,000","Suspended by passive rules = 45,000 - 20,000 = $25,000"]}},{"i":"TCP-I-B-0009","t":"Which statement about the at-risk rules for an individual investor is correct?","mc":{"s":"Which statement about the at-risk rules for an individual investor is correct?","d":"","o":["Any nonrecourse debt on the activity increases the amount at risk when it is secured by the taxpayer's other property","An amount borrowed for the activity from a person who has an interest in the activity, other than as a creditor, is not treated as at risk","The at-risk limitation is applied after the passive activity loss rules, and any loss allowed by the passive rules is at risk by definition","The at-risk limitation applies only to activities that are passive for the taxpayer"],"a":2,"cite":"IRC §465(b)(3); IRC §465(b)(6); Form 6198 instructions","rat":"Loans from an owner or a related party with an interest in the activity are excluded from the amount at risk.","ex":["Nonrecourse debt is generally not at risk. The exception is qualified nonrecourse financing on real property from an unrelated lender.","Loans from an owner or a related party with an interest in the activity are excluded from the amount at risk.","The at-risk rules are applied before the passive activity rules, after basis.","The limitation applies to most trade, business and investment activities, whether passive or not."],"wt":["concept","","trap","concept"],"tags":{"area":"I","group":"B","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"At-risk excludes nonrecourse debt (except qualified real estate financing) and loans from interested persons; it applies before the passive activity rules.","from":"2026-01-01"}},{"i":"TCP-I-B-0012","t":"Kira Sato is a limited partner in a partnership that is a passive activity to her. Her share of the partnership's 2026 loss is $90,000. Her basis in the partnership interest at year-end is $70,000 and her at-risk amount is $50,000. She also has $35,000 of net income from another passive activity. She considers contributing $30,000 in cash to the partnership before December 31, which would raise both her basis and her at-risk amount by $30,000. By how much would the contribution increase her deductible 2026 loss from the partnership?","mc":{"s":"Kira Sato is a limited partner in a partnership that is a passive activity to her. Her share of the partnership's 2026 loss is $90,000. Her basis in the partnership interest at year-end is $70,000 and her at-risk amount is $50,000. She also has $35,000 of net income from another passive activity. She considers contributing $30,000 in cash to the partnership before December 31, which would raise both her basis and her at-risk amount by $30,000. By how much would the contribution increase her deductible 2026 loss from the partnership?","d":"","o":["$0","$20,000","$30,000","$45,000"],"a":1,"cite":"IRC §704(d); IRC §465(a); IRC §469(a)","rat":"The loss must pass three limits in order: basis, at-risk, then passive.","ex":["The loss must pass three limits in order: basis, at-risk, then passive. Without the contribution, the at-risk limit allows $50,000 but only $35,000 of passive income can absorb it. With the contribution, the at-risk limit rises to $80,000 but the passive limit still allows only $35,000. The deductible loss is $35,000 either way, an increase of $0.","Applies only the basis limit, which rises from $70,000 to $90,000 (the loss). The at-risk and passive activity limits are more restrictive.","Applies only the at-risk limit, which rises by $30,000. The passive activity limit caps the loss at $35,000 in both cases.","Subtracts the passive income from the new at-risk limit. This is the loss that is still suspended after the contribution, not the increase in the deduction."],"wt":["","trap","trap","calc"],"tags":{"area":"I","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A loss is limited first by basis, then by the amount at risk, then by the passive activity rules, so extra basis or at-risk amount does not help when the passive limit is binding.","from":"2026-01-01","calc":1,"steps":["Without contribution: min(90,000 loss, 70,000 basis, 50,000 at risk) = 50,000; passive limit 35,000; deductible = 35,000","With contribution: min(90,000, 100,000, 80,000) = 80,000; passive limit 35,000; deductible = 35,000","Increase = 35,000 - 35,000 = 0"]}}],"10":[{"i":"TCP-I-B-0003","t":"Dara Hines has three passive activities in 2026: Activity X has income of $30,000, Activity Y has a loss of $25,000, and Activity Z has a loss of $18,000. She has no prior suspended losses, no other passive income, and she does not qualify for the rental allowance. How much of the disallowed passive loss is allocated to Activity Y?","mc":{"s":"Dara Hines has three passive activities in 2026: Activity X has income of $30,000, Activity Y has a loss of $25,000, and Activity Z has a loss of $18,000. She has no prior suspended losses, no other passive income, and she does not qualify for the rental allowance. How much of the disallowed passive loss is allocated to Activity Y?","d":"","o":["$4,333","$5,442","$6,500","$7,558"],"a":4,"cite":"IRC §469(a); Reg. §1.469-1T(f)(2); Form 8582 instructions","rat":"The net passive loss is $25,000 + $18,000 - $30,000 = $13,000, which is disallowed.","ex":["Divides the disallowed loss among three activities, including the one that has income.","Allocates using Activity Z's share of the losses instead of Activity Y's.","Splits the disallowed loss equally. Allocation is proportional to each activity's loss.","The net passive loss is $25,000 + $18,000 - $30,000 = $13,000, which is disallowed. It is allocated among loss activities in proportion to each activity's loss: $13,000 x $25,000/$43,000 = $7,558."],"wt":["concept","calc","concept",""],"tags":{"area":"I","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Net passive losses are disallowed and allocated to each loss activity in proportion to that activity's loss.","from":"2026-01-01","calc":1,"steps":["Net passive loss = 25,000 + 18,000 - 30,000 = $13,000","Y share = $13,000 x 25,000 / $43,000 = $7,558"]}},{"i":"TCP-I-B-0004","t":"Lena Ford, a single taxpayer, actively participates in a rental house that produced a $30,000 loss in 2026. She also has $8,000 of net income from a separate passive limited partnership interest. Her modified AGI, computed before any passive income or loss, is $138,000. She has no other passive items. How much of the rental loss is suspended and carried to 2027?","mc":{"s":"Lena Ford, a single taxpayer, actively participates in a rental house that produced a $30,000 loss in 2026. She also has $8,000 of net income from a separate passive limited partnership interest. Her modified AGI, computed before any passive income or loss, is $138,000. She has no other passive items. How much of the rental loss is suspended and carried to 2027?","d":"","o":["$16,000","$22,000","$24,000","$30,000"],"a":1,"cite":"IRC §469(i)(1)-(3); Form 8582 instructions; Pub 925","rat":"The rental loss first offsets the $8,000 of passive income, leaving a net passive loss of $22,000.","ex":["The rental loss first offsets the $8,000 of passive income, leaving a net passive loss of $22,000. The special allowance is $25,000 less 50% of the amount by which modified AGI exceeds $100,000: $6,000. So $14,000 of the rental loss is deducted and $16,000 is suspended.","Ignores the special allowance, which lets part of the net passive loss be deducted.","Applies the allowance to the whole loss and forgets that passive income of the other activity absorbs part of the loss first.","Suspends the entire loss. Passive income and the phased-down allowance both permit a deduction."],"wt":["","concept","calc","concept"],"tags":{"area":"I","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Passive income absorbs passive losses first; the $25,000 rental allowance then applies to the remainder, phased out by 50% of MAGI above $100,000.","from":"2026-01-01","calc":1,"steps":["Net passive loss after other passive income = 30,000 - 8,000 = $22,000","Allowance = 25,000 - 0.5 x (138,000 - 100,000) = $6,000","Deducted = 8,000 + $6,000 = $14,000; suspended = $16,000"]}},{"i":"TCP-I-B-0007","t":"Four taxpayers each materially participate in their rental real estate and want to treat their rentals as nonpassive as real estate professionals in 2026. Which taxpayer meets the personal service tests?","mc":{"s":"Four taxpayers each materially participate in their rental real estate and want to treat their rentals as nonpassive as real estate professionals in 2026. Which taxpayer meets the personal service tests?","d":"","o":["Ben, who spent 1,100 hours in real property businesses and 800 hours as an employee of an unrelated company","Anna, who spent 900 hours in real property businesses and 1,000 hours as an employee of an unrelated company","Cara, who spent 700 hours in real property businesses and held no other job at any time during the year","Dev, who spent 800 hours in real property businesses and 800 hours as an employee of an unrelated company"],"a":1,"cite":"IRC §469(c)(7)(B); Reg. §1.469-9; Pub 925","rat":"More than half of his personal service time (1,100 of 1,900 hours) is in real property businesses, and the total exceeds 750 hours.","ex":["More than half of his personal service time (1,100 of 1,900 hours) is in real property businesses, and the total exceeds 750 hours.","Real property time (900 of 1,900 hours) is less than half of her total personal service time.","Her share of time is 100%, but she has fewer than 750 hours in real property businesses.","Exactly half is not enough. The real property time must be more than half of all personal service time."],"wt":["","limit","limit","limit"],"tags":{"area":"I","group":"B","skill":"Application","diff":1},"asof":"2026-09-29","rl":"A real estate professional must spend more than 750 hours in real property trades or businesses and more than half of all personal service hours there.","from":"2026-01-01"}},{"i":"TCP-I-B-0010","t":"Xavier and Yara each have an outside basis and at-risk amount large enough to deduct a $50,000 loss from a partnership in 2026 and otherwise have identical incomes. Xavier is a general partner who works full time in the partnership's business. Yara is a limited partner who does not participate, and she has $10,000 of passive income from another investment. By how much more does the loss reduce Xavier's taxable income than it reduces Yara's?","mc":{"s":"Xavier and Yara each have an outside basis and at-risk amount large enough to deduct a $50,000 loss from a partnership in 2026 and otherwise have identical incomes. Xavier is a general partner who works full time in the partnership's business. Yara is a limited partner who does not participate, and she has $10,000 of passive income from another investment. By how much more does the loss reduce Xavier's taxable income than it reduces Yara's?","d":"","o":["$10,000","$20,000","$30,000","$40,000"],"a":4,"cite":"IRC §469(a); IRC §469(c)(1); Pub 925","rat":"Xavier's loss is nonpassive and reduces his taxable income by $50,000.","ex":["This is Yara's benefit, not the difference between the two.","Doubles Yara's offset against passive income.","Subtracts Yara's passive income twice.","Xavier's loss is nonpassive and reduces his taxable income by $50,000. Yara's loss is passive and is deductible only against her $10,000 of passive income, so it reduces her taxable income by $10,000. The difference is $40,000."],"wt":["trap","calc","calc",""],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A nonpassive loss offsets all income; a passive loss offsets only passive income.","from":"2026-01-01","calc":1,"steps":["Xavier's reduction = 50,000","Yara's reduction = 10,000 (passive income only)","Difference = $40,000"]}},{"i":"TCP-I-B-0011","t":"Jonah Reyes and his wife file jointly and have $400,000 of modified AGI, so the special $25,000 allowance for rental losses is not available. Jonah owns three rental buildings that produce a combined 2026 loss of $60,000, and he is in the 37% bracket. He has a valid election to treat all his rental real estate interests as one activity. His wife does no rental work. Jonah works as an engineer for an unrelated employer for 1,500 hours a year, and spends 900 hours a year on his rentals. He can cut his engineering hours without changing his rental hours. Which choice makes the rental loss deductible against his other income for 2026, and what is the tax saving?","mc":{"s":"Jonah Reyes and his wife file jointly and have $400,000 of modified AGI, so the special $25,000 allowance for rental losses is not available. Jonah owns three rental buildings that produce a combined 2026 loss of $60,000, and he is in the 37% bracket. He has a valid election to treat all his rental real estate interests as one activity. His wife does no rental work. Jonah works as an engineer for an unrelated employer for 1,500 hours a year, and spends 900 hours a year on his rentals. He can cut his engineering hours without changing his rental hours. Which choice makes the rental loss deductible against his other income for 2026, and what is the tax saving?","d":"","o":["Reduce the engineering work to 900 hours, since rental hours would then equal the engineering hours, and save $22,200","Make no change, because 900 rental hours exceeds 750 hours and already meets the test, saving $22,200","No reduction of engineering hours can make the loss deductible, because employee wages prevent real estate professional status, so the saving is $0","Reduce the engineering work to 800 hours, which meets both hour tests, and save $22,200"],"a":4,"cite":"IRC §469(c)(7); Reg. §1.469-9(e); Reg. §1.469-9(g)","rat":"Real estate professional status needs more than 750 hours in real estate trades and more than half of all personal service hours in them.","ex":["Equal hours (900 of 1,800, or 50%) is not more than half. The test requires more than 50% of personal service hours in real estate trades.","The 750-hour test is only one of two tests. At 1,500 engineering hours, 900 / 2,400 = 37.5%, so the more-than-half test fails and the loss stays passive.","Wage work does not bar real estate professional status. The wage hours count only in the more-than-half test, and cutting them makes the test pass.","Real estate professional status needs more than 750 hours in real estate trades and more than half of all personal service hours in them. With 800 engineering hours, 900 / 1,700 = 52.9%. The election to combine the rentals gives him 900 hours in one activity, so he materially participates and the loss is not passive: $60,000 x 37% = $22,200."],"wt":["trap","concept","concept",""],"tags":{"area":"I","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A taxpayer is a real estate professional only if more than half of personal service hours, and more than 750 hours, are in real property trades in which he materially participates; then rental losses are not passive.","from":"2026-01-01","calc":1,"steps":["Test 1: 900 hours > 750 hours (passes at any engineering level)","Test 2 at 1,500 engineering hours: 900 / (900 + 1,500) = 37.5%, fails","At 900 engineering hours: 900 / 1,800 = 50%, not more than half, fails","At 800 engineering hours: 900 / 1,700 = 52.9%, passes; loss becomes nonpassive: 60,000 x 37% = 22,200"]}}],"11":[{"i":"TCP-I-B-0005","t":"Ted Wilkes sold his entire interest in a rental activity to an unrelated buyer in 2026 in a fully taxable sale. The activity had a current-year passive loss of $6,000 before the sale, $40,000 of suspended passive losses from earlier years, and Ted's gain on the sale was $25,000. He has no other passive items. By what net amount does the activity reduce his 2026 adjusted gross income?","mc":{"s":"Ted Wilkes sold his entire interest in a rental activity to an unrelated buyer in 2026 in a fully taxable sale. The activity had a current-year passive loss of $6,000 before the sale, $40,000 of suspended passive losses from earlier years, and Ted's gain on the sale was $25,000. He has no other passive items. By what net amount does the activity reduce his 2026 adjusted gross income?","d":"","o":["$6,000","$15,000","$21,000","$46,000"],"a":3,"cite":"IRC §469(g)(1)(A); Form 8582 instructions; Pub 925","rat":"On a fully taxable disposition of the entire interest all losses are released.","ex":["Allows only the current loss and leaves suspended losses suspended. A full taxable disposition releases them.","Forgets the current-year loss of the activity, which is also deductible.","On a fully taxable disposition of the entire interest all losses are released. The activity's net effect is the gain of $25,000 less the current loss of $6,000 and the suspended losses of $40,000: $21,000 reduction in AGI.","Leaves out the gain on the sale, which offsets the losses."],"wt":["concept","calc","","calc"],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A fully taxable disposition of a passive activity to an unrelated party frees all suspended losses to offset the gain and then other income.","from":"2026-01-01","calc":1,"steps":["Losses released = 6,000 + 40,000 = $46,000","Net reduction = $46,000 - 25,000 = $21,000"]}},{"i":"TCP-I-B-0006","t":"Rhea Colton owns a rental property with $30,000 of suspended passive losses. The property has a fair market value of $200,000 and an adjusted basis of $120,000. She gives her entire interest to her son in 2026. Which statement about the suspended losses is correct?","mc":{"s":"Rhea Colton owns a rental property with $30,000 of suspended passive losses. The property has a fair market value of $200,000 and an adjusted basis of $120,000. She gives her entire interest to her son in 2026. Which statement about the suspended losses is correct?","d":"","o":["Rhea deducts the suspended losses in 2026 because she has disposed of her entire interest in the activity","Rhea's son inherits the suspended losses and may deduct them against his passive income from other activities","Rhea deducts the suspended losses up to the $80,000 built-in gain, and any excess is added to the son's basis","Rhea cannot deduct the suspended losses, and her son's basis in the property is increased by them"],"a":4,"cite":"IRC §469(j)(6); Form 8582 instructions; Pub 925","rat":"A gift is not a taxable disposition.","ex":["The release of suspended losses requires a fully taxable disposition. A gift is not taxable.","Suspended losses do not carry over to the donee as passive losses; they become part of his basis.","No deduction is available on a gift. The gain limitation is not a rule for these losses.","A gift is not a taxable disposition. The suspended losses are not deductible by the donor; they are added to the donee's basis instead."],"wt":["concept","concept","trap",""],"tags":{"area":"I","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A gift of a passive activity does not release suspended losses; they increase the donee's basis.","from":"2026-01-01"}}],"12":[{"i":"TCP-I-C-0001","t":"Beth Nolan wants to help her grandson, who is not her dependent, with college costs in 2026. Which payment is excluded from gift tax without using her annual exclusion or filing a gift tax return?","mc":{"s":"Beth Nolan wants to help her grandson, who is not her dependent, with college costs in 2026. Which payment is excluded from gift tax without using her annual exclusion or filing a gift tax return?","d":"","o":["A payment of the same tuition amount made to her grandson, who then pays the college","A payment of the grandson's room and board made directly to the college","A payment of tuition made directly to the college for her grandson","A payment of the tuition made to the grandson's parents, who then pay the college"],"a":3,"cite":"IRC §2503(e); Reg. §25.2503-6; Form 709 instructions","rat":"Tuition paid directly to the educational institution is excluded from taxable gifts regardless of amount and does not use the annual exclusion.","ex":["The unlimited exclusion applies only to payments made directly to the institution. A payment to the grandson is a gift eligible for the annual exclusion.","The exclusion covers tuition only, not room and board, books or supplies.","Tuition paid directly to the educational institution is excluded from taxable gifts regardless of amount and does not use the annual exclusion.","A payment to the parents is a gift to them. Only direct payments to the school qualify."],"wt":["trap","concept","","trap"],"tags":{"area":"I","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Direct payments of tuition to a school, or medical costs to a provider, are excluded from gift tax without limit.","from":"2026-01-01"}},{"i":"TCP-I-C-0008","t":"Which of the following requires the donor to file a federal gift tax return, Form 709, for 2026? Assume the annual exclusion is $19,000 per donee.","mc":{"s":"Which of the following requires the donor to file a federal gift tax return, Form 709, for 2026? Assume the annual exclusion is $19,000 per donee.","d":"","o":["A gift of $30,000 in cash to a son","Gifts of $15,000 in cash to each of three children","An outright gift of $500,000 in cash to the donor's U.S. citizen spouse","Payment of $40,000 of tuition directly to a grandchild's university"],"a":1,"cite":"IRC §6019(a); IRC §2503(b); Form 709 instructions","rat":"A present-interest gift above the annual exclusion requires a return even if no tax is due.","ex":["A present-interest gift above the annual exclusion requires a return even if no tax is due.","Each gift is within the annual exclusion, so no return is required.","An outright gift to a citizen spouse qualifies for the marital deduction and does not require a return.","A direct tuition payment is excluded, and no return is required."],"wt":["","limit","concept","concept"],"tags":{"area":"I","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A gift tax return is required for gifts over the annual exclusion, gifts of future interests, or split gifts; direct tuition payments and outright citizen spouse gifts need none.","from":"2026-01-01"}},{"i":"TCP-I-C-0009","t":"Nolan and Iris Berg, a married couple, want to contribute a lump sum to a 529 plan for their grandson in 2026 without using any lifetime exemption and without paying gift tax. They elect to treat the contribution as made evenly over five years and to split gifts. The annual exclusion is $19,000 per donor per donee. What is the largest lump sum they can contribute?","mc":{"s":"Nolan and Iris Berg, a married couple, want to contribute a lump sum to a 529 plan for their grandson in 2026 without using any lifetime exemption and without paying gift tax. They elect to treat the contribution as made evenly over five years and to split gifts. The annual exclusion is $19,000 per donor per donee. What is the largest lump sum they can contribute?","d":"","o":["$38,000","$95,000","$190,000","$380,000"],"a":3,"cite":"IRC §529(c)(2)(B); IRC §2513; Pub 970","rat":"Each spouse may use five years of the annual exclusion in one year: $19,000 x 5 = $95,000.","ex":["Applies only one year's exclusion for each spouse. The five-year election allows five years' worth.","Allows five years of exclusion for one spouse only. Gift splitting allows both spouses' exclusions.","Each spouse may use five years of the annual exclusion in one year: $19,000 x 5 = $95,000. With gift splitting the two spouses together can contribute $190,000.","Doubles the amount again. Two spouses are the only donors."],"wt":["concept","concept","","calc"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A 529 contribution may be averaged over five years of annual exclusions per donor; splitting doubles it for a married couple.","from":"2026-01-01","calc":1,"steps":["One donor: 19,000 x 5 = $95,000","Two spouses: $95,000 x 2 = $190,000"]}}],"13":[{"i":"TCP-I-C-0002","t":"Which statement about the federal gift tax annual exclusion and marital deduction is correct for 2026?","mc":{"s":"Which statement about the federal gift tax annual exclusion and marital deduction is correct for 2026?","d":"","o":["Gifts of a future interest in a trust qualify for the annual exclusion if the trust is irrevocable and long-term","Gifts of any amount to a spouse who is not a U.S. citizen qualify for the unlimited marital deduction","The annual exclusion is a single lifetime cap that is gradually used up as the donor makes gifts of any kind","Each donee may receive a present-interest gift up to the annual exclusion, and outright gifts to a citizen spouse are deductible"],"a":4,"cite":"IRC §2503(b); IRC §2523(a); IRC §2523(i)","rat":"The annual exclusion is per donee for present interests, and the unlimited marital deduction applies to outright gifts to a U.S.","ex":["A future interest does not qualify for the annual exclusion unless the beneficiary has a present right to use or enjoy the property.","For a noncitizen spouse the marital deduction is replaced by a dollar-limited annual exclusion.","The annual exclusion is available each year per donee. The unified credit is the cumulative amount.","The annual exclusion is per donee for present interests, and the unlimited marital deduction applies to outright gifts to a U.S. citizen spouse."],"wt":["concept","limit","concept",""],"tags":{"area":"I","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The annual exclusion is per donee per year for present interests; the marital deduction is unlimited for a citizen spouse.","from":"2026-01-01"}}],"14":[{"i":"TCP-I-C-0003","t":"In 2026 Robert Vance, who is married to a U.S. citizen, made these gifts: $80,000 in cash to his daughter, $30,000 in cash to his son, $50,000 paid directly to a university for a grandchild's tuition, and $200,000 in cash to his wife. The annual exclusion is $19,000 per donee. What are his total taxable gifts for 2026?","mc":{"s":"In 2026 Robert Vance, who is married to a U.S. citizen, made these gifts: $80,000 in cash to his daughter, $30,000 in cash to his son, $50,000 paid directly to a university for a grandchild's tuition, and $200,000 in cash to his wife. The annual exclusion is $19,000 per donee. What are his total taxable gifts for 2026?","d":"","o":["$72,000","$103,000","$110,000","$253,000"],"a":1,"cite":"IRC §2503(b); IRC §2503(e); IRC §2523(a); IRC §2512","rat":"The direct tuition payment is excluded and the gift to his wife qualifies for the marital deduction.","ex":["The direct tuition payment is excluded and the gift to his wife qualifies for the marital deduction. The taxable gifts are ($80,000 - $19,000) + ($30,000 - $19,000) = $72,000.","Treats the tuition payment as a gift eligible for the annual exclusion. Direct tuition payments are excluded entirely.","Ignores the annual exclusion for each donee.","Includes the gift to his wife. Gifts to a citizen spouse qualify for the unlimited marital deduction."],"wt":["","concept","concept","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Taxable gifts = gifts less annual exclusions, direct tuition or medical payments and marital or charitable deductions.","from":"2026-01-01","calc":1,"steps":["Daughter: 80,000 - 19,000 = $61,000","Son: 30,000 - 19,000 = $11,000","Tuition paid directly: excluded; spouse gift: marital deduction","Total = $72,000"]}},{"i":"TCP-I-C-0004","t":"In 2026 Linda Park gave $100,000 in cash to her nephew. Linda's husband, who made no other gifts, consents to split the gift, and both file gift tax returns. The annual exclusion is $19,000 per donor per donee. What total taxable gifts do Linda and her husband report for the gift combined?","mc":{"s":"In 2026 Linda Park gave $100,000 in cash to her nephew. Linda's husband, who made no other gifts, consents to split the gift, and both file gift tax returns. The annual exclusion is $19,000 per donor per donee. What total taxable gifts do Linda and her husband report for the gift combined?","d":"","o":["$31,000","$38,000","$50,000","$62,000"],"a":4,"cite":"IRC §2513(a); IRC §2503(b); Form 709 instructions","rat":"With splitting each spouse is treated as giving half, $50,000.","ex":["This is the taxable gift of each spouse, not the combined amount.","Reports the two annual exclusions rather than taxable gifts.","Reports each spouse's share of the gift with no annual exclusion.","With splitting each spouse is treated as giving half, $50,000. Each claims a $19,000 exclusion, so each has $31,000 of taxable gifts, or $62,000 combined."],"wt":["trap","trap","concept",""],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Gift splitting lets spouses treat a gift as made half by each, so two annual exclusions apply.","from":"2026-01-01","calc":1,"steps":["Each spouse's share = $50,000","Taxable per spouse = $50,000 - 19,000 = $31,000","Combined = $62,000"]}},{"i":"TCP-I-C-0005","t":"Maya Duarte made taxable gifts of $9,000,000 in earlier years and paid no gift tax. In 2026 she made taxable gifts of $6,900,000. Assume the basic exclusion amount is $15,000,000 and the tax rate on cumulative taxable gifts above it is 40%. What gift tax does she owe for 2026?","mc":{"s":"Maya Duarte made taxable gifts of $9,000,000 in earlier years and paid no gift tax. In 2026 she made taxable gifts of $6,900,000. Assume the basic exclusion amount is $15,000,000 and the tax rate on cumulative taxable gifts above it is 40%. What gift tax does she owe for 2026?","d":"","o":["$360,000","$900,000","$2,760,000","$6,360,000"],"a":1,"cite":"IRC §2001(c); IRC §2505(a); IRC §2502","rat":"Cumulative taxable gifts are $9,000,000 + $6,900,000 = $15,900,000.","ex":["Cumulative taxable gifts are $9,000,000 + $6,900,000 = $15,900,000. The excess over the $15,000,000 exclusion is $900,000, taxed at 40%: $360,000.","Reports the excess over the exclusion without applying the 40% rate.","Taxes the 2026 gifts alone and ignores the exclusion already used against prior gifts and the amount still unused.","Taxes cumulative gifts without allowing the exclusion."],"wt":["","calc","concept","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Gift tax is computed on cumulative taxable gifts, reduced by the unified credit equal to tax on the basic exclusion amount.","from":"2026-07-01","calc":1,"steps":["Cumulative = 9,000,000 + 6,900,000 = $15,900,000","Excess over 15,000,000 = $900,000","Tax = 40% x $900,000 = $360,000"]}},{"i":"TCP-I-C-0012","t":"In 2026 Hal and Eve Dorn, who are married and consent to split all gifts, make these transfers. Hal gives $200,000 to a 529 plan for his granddaughter Ada and elects to spread the gift over five years. Eve gives $15,000 in cash to their grandson Ben. Hal also pays $12,000 of tuition directly to Ben's university. Assume the annual exclusion is $19,000 per donee and ignore the lifetime exemption. What total amount of taxable gifts do Hal and Eve report on their two gift tax returns for 2026?","mc":{"s":"In 2026 Hal and Eve Dorn, who are married and consent to split all gifts, make these transfers. Hal gives $200,000 to a 529 plan for his granddaughter Ada and elects to spread the gift over five years. Eve gives $15,000 in cash to their grandson Ben. Hal also pays $12,000 of tuition directly to Ben's university. Assume the annual exclusion is $19,000 per donee and ignore the lifetime exemption. What total amount of taxable gifts do Hal and Eve report on their two gift tax returns for 2026?","d":"","o":["$0","$5,000","$10,000","$105,000"],"a":3,"cite":"IRC §2513(a); IRC §529(c)(2)(B); IRC §2503(e); IRC §2503(b)","rat":"With splitting, each spouse is treated as giving half: $100,000 to Ada and $7,500 to Ben.","ex":["Assumes the five-year election covers the whole $200,000. Two spouses can apply five exclusions each, $190,000 in total, so $10,000 is taxable.","Counts the taxable excess for only one spouse. Each spouse is treated as making half of the gift, so both returns show a taxable amount.","With splitting, each spouse is treated as giving half: $100,000 to Ada and $7,500 to Ben. The five-year election lets each spouse use five annual exclusions ($95,000) on the 529 gift, leaving $5,000 taxable each, or $10,000. Ben's $7,500 share each is under the $19,000 exclusion, and the direct tuition payment is excluded.","Ignores gift splitting and reports the whole $105,000 excess on Hal's return. With splitting, the $200,000 gift uses two donors' five-year exclusions."],"wt":["concept","trap","","calc"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Gift splitting treats each spouse as making half of every gift, and a 529 five-year election lets each donor apply five annual exclusions to a large contribution; direct tuition payments are excluded.","from":"2026-01-01","calc":1,"steps":["Splitting: each spouse gives half: Ada 100,000 each, Ben 7,500 each","Five-year election: each spouse excludes 5 x 19,000 = 95,000 for Ada; taxable = 100,000 - 95,000 = 5,000 each = 10,000","Ben: 7,500 < 19,000 exclusion each, taxable 0; tuition of 12,000 paid directly is excluded","Total taxable gifts = 10,000"]}}],"15":[{"i":"TCP-I-C-0006","t":"Frank Duarte, age 82 and in poor health, owns stock worth $100,000 with a basis of $20,000. His estate is well below the federal estate tax exemption. He can give the stock to his daughter now or leave it to her in his will, and she plans to sell it soon after receiving it. Her long-term capital gains rate is 20%, and the value will not change. How much less federal income tax does she pay if she inherits the stock instead of receiving it as a gift?","mc":{"s":"Frank Duarte, age 82 and in poor health, owns stock worth $100,000 with a basis of $20,000. His estate is well below the federal estate tax exemption. He can give the stock to his daughter now or leave it to her in his will, and she plans to sell it soon after receiving it. Her long-term capital gains rate is 20%, and the value will not change. How much less federal income tax does she pay if she inherits the stock instead of receiving it as a gift?","d":"","o":["$4,000","$8,000","$12,000","$16,000"],"a":4,"cite":"IRC §1014(a); IRC §1015(a); Pub 551","rat":"A donee takes the donor's basis ($20,000), so a sale produces $80,000 of gain.","ex":["Applies the rate to the basis, not to the built-in gain.","Applies a 10% rate instead of the 20% rate.","Applies a 15% rate instead of the 20% rate.","A donee takes the donor's basis ($20,000), so a sale produces $80,000 of gain. An heir's basis is stepped up to fair market value at death ($100,000), so the sale produces no gain. The saving is $80,000 x 20% = $16,000."],"wt":["concept","limit","limit",""],"tags":{"area":"I","group":"C","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Property held until death gets a stepped-up basis; a lifetime gift carries over the donor's basis.","from":"2026-01-01","calc":1,"steps":["Gift: gain on sale = 100,000 - 20,000 = $80,000; tax = $16,000","Bequest: basis = fair market value, gain = 0","Difference = $16,000"]}},{"i":"TCP-I-C-0007","t":"Paul Stein gave his niece stock with a fair market value of $130,000 and an adjusted basis to him of $65,000. He paid $18,000 of gift tax on the gift. The annual exclusion was $19,000. What is his niece's basis in the stock for computing gain?","mc":{"s":"Paul Stein gave his niece stock with a fair market value of $130,000 and an adjusted basis to him of $65,000. He paid $18,000 of gift tax on the gift. The annual exclusion was $19,000. What is his niece's basis in the stock for computing gain?","d":"","o":["$65,000","$74,000","$75,541","$83,000"],"a":3,"cite":"IRC §1015(d)(6); Reg. §1.1015-5(c); Pub 551","rat":"The niece's basis is the donor's basis plus the part of the gift tax attributable to net appreciation: $18,000 x ($65,000 / $111,000) = $10,541.","ex":["Uses only the donor's basis. The gift tax paid on appreciation is added to basis.","Computes the appreciation share against the full fair market value instead of the value net of the annual exclusion.","The niece's basis is the donor's basis plus the part of the gift tax attributable to net appreciation: $18,000 x ($65,000 / $111,000) = $10,541. Basis = $65,000 + $10,541 = $75,541.","Adds all of the gift tax to basis. Only the part attributable to appreciation is added."],"wt":["concept","calc","","concept"],"tags":{"area":"I","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The donee's basis increases by the gift tax paid multiplied by the ratio of net appreciation to the amount of the gift.","from":"2026-01-01","calc":1,"steps":["Net appreciation = 130,000 - 65,000 = $65,000","Amount of gift = 130,000 - 19,000 = $111,000","Adjustment = 18,000 x $65,000 / $111,000 = $10,541","Basis = $75,541"]}},{"i":"TCP-I-C-0010","t":"Lara Ortega plans to transfer $100,000 to her grandson in 2026. Alternatively she could pay his $40,000 tuition and $12,000 of medical bills directly to the providers, and give him the remaining $48,000 in cash. The annual exclusion is $19,000. By how much do direct payments reduce her taxable gifts compared with giving the whole $100,000 to him in cash?","mc":{"s":"Lara Ortega plans to transfer $100,000 to her grandson in 2026. Alternatively she could pay his $40,000 tuition and $12,000 of medical bills directly to the providers, and give him the remaining $48,000 in cash. The annual exclusion is $19,000. By how much do direct payments reduce her taxable gifts compared with giving the whole $100,000 to him in cash?","d":"","o":["$19,000","$29,000","$40,000","$52,000"],"a":4,"cite":"IRC §2503(e); IRC §2503(b); Reg. §25.2503-6","rat":"All cash produces taxable gifts of $100,000 - $19,000 = $81,000.","ex":["The annual exclusion applies under both plans, so it does not change the difference.","This is the taxable gift under the direct-payment plan, not the reduction.","Reports only the tuition paid directly.","All cash produces taxable gifts of $100,000 - $19,000 = $81,000. With direct payments, tuition and medical bills are excluded and only $48,000 - $19,000 = $29,000 is taxable. The reduction is $52,000."],"wt":["concept","trap","trap",""],"tags":{"area":"I","group":"C","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Direct payments of tuition and medical costs are excluded from gifts in addition to the annual exclusion.","from":"2026-01-01","calc":1,"steps":["All cash: 100,000 - 19,000 = $81,000","Direct payments: cash 48,000 - 19,000 = $29,000","Reduction = $52,000"]}},{"i":"TCP-I-C-0011","t":"Ines Varga, age 78, wants to give her son $200,000 of securities now. She owns Stock A (worth $200,000, basis $40,000) and Stock B (worth $200,000, basis $260,000), both held long term. She will keep whichever stock she does not give until death, and her estate is well below the estate tax exemption. Her son will sell whatever he receives right away. Long-term capital gain is taxed at 15% for both, and Ines has large capital gains this year, so any loss she realizes saves tax at 15%. Plan 1: give Stock A. Plan 2: give Stock B. Plan 3: sell Stock B, and give the $200,000 of cash. Which plan gives the lowest combined income tax for Ines and her son?","mc":{"s":"Ines Varga, age 78, wants to give her son $200,000 of securities now. She owns Stock A (worth $200,000, basis $40,000) and Stock B (worth $200,000, basis $260,000), both held long term. She will keep whichever stock she does not give until death, and her estate is well below the estate tax exemption. Her son will sell whatever he receives right away. Long-term capital gain is taxed at 15% for both, and Ines has large capital gains this year, so any loss she realizes saves tax at 15%. Plan 1: give Stock A. Plan 2: give Stock B. Plan 3: sell Stock B, and give the $200,000 of cash. Which plan gives the lowest combined income tax for Ines and her son?","d":"","o":["Plan 1, with combined tax of $24,000","Plan 2, because the son sells with no gain or loss and Ines keeps Stock A for a stepped-up basis","Plans 2 and 3 equally, each with combined tax of $0","Plan 3, which produces a net tax saving of $9,000"],"a":4,"cite":"IRC §1015(a); IRC §1014(a); IRC §1211(b); Reg. §1.1015-1(a)(2)","rat":"Ines sells Stock B and uses the $60,000 loss against gains, saving $60,000 x 15% = $9,000.","ex":["The son takes Stock A with Ines's $40,000 basis and taxes $160,000 of gain at 15%, which is $24,000. Ines also loses the step-up on Stock A.","Combined tax is $0, but the loss is wasted: for a loss the son's basis is the $200,000 value, so his sale shows no loss, and Ines's $60,000 loss disappears at her death.","Plan 3 produces a $9,000 saving while Plan 2 produces none. A gift of loss property gives up the loss for both the donor and the donee.","Ines sells Stock B and uses the $60,000 loss against gains, saving $60,000 x 15% = $9,000. The cash gift carries no income tax for the son, and Stock A, held until death, gets a step-up. Combined tax is negative $9,000."],"wt":["concept","trap","concept",""],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A gift of appreciated property carries over the donor's basis, and a gift of loss property gives the donee no loss deduction; a donor with loss property should sell it and give the cash, and keep appreciated property for a step-up at death.","from":"2026-01-01","calc":1,"steps":["Plan 1: son's gain = 200,000 - 40,000 = 160,000; tax = 160,000 x 15% = 24,000; B basis steps down at death","Plan 2: loss basis = 200,000 (value), so son sells at 200,000 with no gain or loss; tax 0, and the 60,000 loss is never used","Plan 3: loss = 260,000 - 200,000 = 60,000; saving = 60,000 x 15% = 9,000; Stock A keeps its step-up","Lowest combined tax is Plan 3 (net saving of 9,000)"]}},{"i":"TCP-I-C-0013","t":"Gwen Alvarez owns a rental building worth $400,000 with an adjusted basis of $100,000, subject to a $150,000 mortgage. Plan A: she gives the building to her son, who assumes the mortgage. Plan B: she uses $150,000 of her own cash to pay off the mortgage and then gives the building to her son free and clear. In either plan the son sells the building immediately for $400,000 (and repays any mortgage). Ignore gift tax rates, depreciation recapture, and the annual exclusion. Compare Plan A with Plan B. Which statement is correct?","mc":{"s":"Gwen Alvarez owns a rental building worth $400,000 with an adjusted basis of $100,000, subject to a $150,000 mortgage. Plan A: she gives the building to her son, who assumes the mortgage. Plan B: she uses $150,000 of her own cash to pay off the mortgage and then gives the building to her son free and clear. In either plan the son sells the building immediately for $400,000 (and repays any mortgage). Ignore gift tax rates, depreciation recapture, and the annual exclusion. Compare Plan A with Plan B. Which statement is correct?","d":"","o":["Plan A produces less combined gain, $250,000, and the gift is $250,000 instead of $400,000","Plan A produces more combined gain, $350,000, and the gift is $250,000 instead of $400,000","Plan A produces the same $300,000 of combined gain as Plan B, and the gift is $250,000 instead of $400,000","Plan A produces the same $300,000 of combined gain as Plan B, and the gift is $400,000 in both plans"],"a":3,"cite":"Reg. §1.1001-1(e); Reg. §1.1015-4; IRC §2512(b)","rat":"In Plan A the transfer is part gift, part sale.","ex":["This counts only the son's gain in Plan A. Gwen also recognizes $50,000 of gain on the part of the transfer that is a sale.","Adds Gwen's $50,000 gain to the son's gain measured from her $100,000 basis ($300,000). The son's basis is raised to $150,000, the amount paid, which removes the overlap.","In Plan A the transfer is part gift, part sale. Gwen's gain is $150,000 debt relief less her $100,000 basis, or $50,000. The son's basis is the greater of the debt assumed or her basis, $150,000, so his gain is $250,000. Combined gain is $300,000, the same as Plan B (son's gain of $400,000 - $100,000). The gift is $400,000 - $150,000 = $250,000 in Plan A, against $400,000 in Plan B.","The debt the son assumes is consideration for the transfer, so the gift is only the value above that. In Plan B, Gwen pays off her own mortgage and the whole $400,000 is a gift."],"wt":["trap","calc","","concept"],"tags":{"area":"I","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"When property subject to debt is given and the donee assumes the debt, the transfer is part sale and part gift: the donor's gain is the debt relief less basis, the gift is the value less the debt, and the donee's basis is the greater of the amount paid or the donor's basis.","from":"2026-01-01","calc":1,"steps":["Plan A: donor gain = 150,000 - 100,000 = 50,000; son's basis = max(150,000, 100,000) = 150,000; son's gain = 400,000 - 150,000 = 250,000; combined gain = 300,000","Plan A gift = 400,000 - 150,000 = 250,000","Plan B: no gain to Gwen; son's basis = 100,000; son's gain = 300,000; gift = 400,000","Combined gain is 300,000 in both plans; the gift differs"]}}],"16":[{"i":"TCP-I-D-0001","t":"Ellen Ross, age 62, opened a Roth IRA eight years ago, made only after-tax contributions, and in 2026 withdraws the entire account balance, which includes investment earnings. Which statement about the distribution is correct?","mc":{"s":"Ellen Ross, age 62, opened a Roth IRA eight years ago, made only after-tax contributions, and in 2026 withdraws the entire account balance, which includes investment earnings. Which statement about the distribution is correct?","d":"","o":["The earnings are ordinary income and subject to the 10% additional tax because she took the entire balance","It is a qualified distribution, so neither her contributions nor the earnings are included in gross income","The earnings are ordinary income, but the 10% additional tax does not apply because she is over 59 1/2","The earnings are excluded only to the extent the funds are used for a first-time home purchase"],"a":2,"cite":"IRC §408A(d)(2); IRC §408A(d)(2)(A); Pub 590-B","rat":"A Roth distribution after age 59 1/2 and after the five-year holding period is qualified, so the earnings are excluded along with the contributions.","ex":["The additional tax applies to nonqualified distributions before age 59 1/2. This distribution is qualified.","A Roth distribution after age 59 1/2 and after the five-year holding period is qualified, so the earnings are excluded along with the contributions.","This mixes the rules. The five-year period and age test are both met, so the earnings are not taxed either.","The first-home rule is a separate exception for early distributions. It is not needed for a qualified distribution."],"wt":["concept","","concept","trap"],"tags":{"area":"I","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"A Roth IRA distribution is qualified, and tax-free, after a five-year period if the owner is 59 1/2 or older, disabled, or has died, or for a first-home purchase.","from":"2026-01-01"}},{"i":"TCP-I-D-0002","t":"Rosa Vidal, age 63, paid $100,000 for a nonqualified deferred annuity contract that is now worth $130,000. She withdraws $20,000 in 2026 without annuitizing the contract. How much of the withdrawal is included in her gross income?","mc":{"s":"Rosa Vidal, age 63, paid $100,000 for a nonqualified deferred annuity contract that is now worth $130,000. She withdraws $20,000 in 2026 without annuitizing the contract. How much of the withdrawal is included in her gross income?","d":"","o":["$4,615","$20,000","$30,000","$130,000"],"a":2,"cite":"IRC §72(e)(2)(B); IRC §72(e)(5); Pub 575","rat":"Withdrawals from a nonqualified deferred annuity before annuitization are treated as earnings first (last-in, first-out).","ex":["Applies a pro rata basis recovery. Withdrawals before annuitization come out earnings first.","Withdrawals from a nonqualified deferred annuity before annuitization are treated as earnings first (last-in, first-out). Earnings are $130,000 - $100,000 = $30,000, which exceeds the $20,000 withdrawal, so the entire withdrawal is taxable.","Includes all of the contract's earnings even though only a part was withdrawn.","Reports the value of the contract as income."],"wt":["concept","","calc","trap"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Partial withdrawals from a nonqualified deferred annuity are taxed as earnings first, up to the total gain in the contract.","from":"2026-01-01","calc":1,"steps":["Gain in contract = 130,000 - 100,000 = $30,000","Taxable = lesser of withdrawal 20,000 and gain $30,000 = $20,000"]}},{"i":"TCP-I-D-0003","t":"Amy Kwon, age 44, has one traditional IRA holding $90,000, of which $9,000 is from nondeductible contributions she made in earlier years. She has no other IRAs. In 2026 she converts $30,000 of the IRA to a Roth IRA. Assume the total IRA balance at year end, counting the amount converted, is still $90,000. How much of the conversion is included in her gross income?","mc":{"s":"Amy Kwon, age 44, has one traditional IRA holding $90,000, of which $9,000 is from nondeductible contributions she made in earlier years. She has no other IRAs. In 2026 she converts $30,000 of the IRA to a Roth IRA. Assume the total IRA balance at year end, counting the amount converted, is still $90,000. How much of the conversion is included in her gross income?","d":"","o":["$3,000","$21,000","$27,000","$30,000"],"a":3,"cite":"IRC §408(d)(2); IRC §408A(d)(3); Form 8606 instructions","rat":"The pro rata rule treats each distribution as part taxable and part basis: the nontaxable fraction is $9,000/$90,000 = 10%.","ex":["Computes the nontaxable part instead of the taxable part.","Subtracts all of the basis from the amount converted. Basis is recovered in proportion to the whole IRA balance, not first.","The pro rata rule treats each distribution as part taxable and part basis: the nontaxable fraction is $9,000/$90,000 = 10%. The taxable amount is $30,000 x 90% = $27,000.","Ignores the nondeductible basis."],"wt":["trap","concept","","concept"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Distributions and conversions from traditional IRAs with basis are taxable in proportion to pre-tax dollars in all IRAs.","from":"2026-01-01","calc":1,"steps":["Nontaxable fraction = 9,000 / 90,000 = 10%","Taxable = 30,000 x (1 - 9,000/90,000) = $27,000"]}},{"i":"TCP-I-D-0004","t":"Pat Simon has $7,000 of pre-tax earnings available to save and expects the money to double before retirement. Pat's marginal rate is 24% now and is expected to be 32% in retirement. Under the traditional IRA choice Pat deducts a $7,000 contribution and pays tax on the withdrawal. Under the Roth IRA choice Pat pays tax on the $7,000 first and contributes the rest. Ignoring all other rules, which choice leaves more after tax at retirement, and by how much?","mc":{"s":"Pat Simon has $7,000 of pre-tax earnings available to save and expects the money to double before retirement. Pat's marginal rate is 24% now and is expected to be 32% in retirement. Under the traditional IRA choice Pat deducts a $7,000 contribution and pays tax on the withdrawal. Under the Roth IRA choice Pat pays tax on the $7,000 first and contributes the rest. Ignoring all other rules, which choice leaves more after tax at retirement, and by how much?","d":"","o":["The traditional IRA, by $1,120","The Roth IRA, by $2,800","The Roth IRA, by $1,120","The two choices leave the same amount after tax"],"a":3,"cite":"IRC §408(a); IRC §408A(a); Pub 590-A","rat":"Traditional: $7,000 doubles to $14,000 and is taxed at 32%, leaving $9,520.","ex":["Reverses the comparison. The higher rate at retirement favors paying tax now.","Compares the tax paid in nominal dollars (retirement tax against tax now) instead of comparing after-tax accumulations.","Traditional: $7,000 doubles to $14,000 and is taxed at 32%, leaving $9,520. Roth: $7,000 less 24% tax leaves $5,320, which doubles to $10,640 tax-free. The Roth leaves $1,120 more.","This holds only if the rate at retirement equals the rate now, which is not the case here."],"wt":["concept","calc","","trap"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"When the retirement rate exceeds the current rate, paying tax now through a Roth increases the after-tax amount; equal rates give equal results.","from":"2026-01-01","calc":1,"steps":["Traditional: 7,000 x 2 = $14,000; x (1 - 0.32) = $9,520","Roth: 7,000 x (1 - 0.24) = $5,320; x 2 = $10,640","Difference = $1,120"]}},{"i":"TCP-I-D-0005","t":"Walt Emery was born in 1952 and turned 74 in 2026. His traditional IRA balance was $1,000,000 on December 31, 2025 and $1,080,000 on December 31, 2026. The uniform lifetime table factors are 26.5 at age 73, 25.5 at age 74 and 24.6 at age 75. What is his required minimum distribution for 2026?","mc":{"s":"Walt Emery was born in 1952 and turned 74 in 2026. His traditional IRA balance was $1,000,000 on December 31, 2025 and $1,080,000 on December 31, 2026. The uniform lifetime table factors are 26.5 at age 73, 25.5 at age 74 and 24.6 at age 75. What is his required minimum distribution for 2026?","d":"","o":["$37,736","$39,216","$40,650","$42,353"],"a":2,"cite":"IRC §401(a)(9); IRC §408(a)(6); Pub 590-B","rat":"The 2026 distribution uses the prior year-end balance and the factor for his age at the end of 2026 (74): $1,000,000 / 25.5 = $39,216.","ex":["Uses the age 73 factor. The factor is for the age reached in 2026.","The 2026 distribution uses the prior year-end balance and the factor for his age at the end of 2026 (74): $1,000,000 / 25.5 = $39,216.","Uses the age 75 factor.","Uses the December 31, 2026 balance. The required distribution is based on the prior year-end balance."],"wt":["limit","","limit","concept"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"The RMD equals the prior December 31 account balance divided by the uniform lifetime factor for the age attained during the year.","from":"2026-01-01","calc":1,"steps":["RMD = 1,000,000 / 25.5 = $39,216"]}},{"i":"TCP-I-D-0006","t":"Sue Blake, age 45, withdrew $20,000 from her traditional IRA (all pre-tax dollars) in 2026. She used $10,000 of it to buy her first home under the rules for first-time homebuyers, and spent the remaining $10,000 on a vacation. Her marginal rate is 24%. What is the total of her federal income tax and additional tax on the early distribution?","mc":{"s":"Sue Blake, age 45, withdrew $20,000 from her traditional IRA (all pre-tax dollars) in 2026. She used $10,000 of it to buy her first home under the rules for first-time homebuyers, and spent the remaining $10,000 on a vacation. Her marginal rate is 24%. What is the total of her federal income tax and additional tax on the early distribution?","d":"","o":["$1,000","$4,800","$5,800","$6,800"],"a":3,"cite":"IRC §72(t)(1); IRC §72(t)(2)(F); IRC §72(t)(8)","rat":"The whole withdrawal is taxable: $20,000 x 24% = $4,800.","ex":["Counts only the additional tax and omits the income tax.","Omits the 10% additional tax on the part that does not qualify for the exception.","The whole withdrawal is taxable: $20,000 x 24% = $4,800. The 10% additional tax applies only to the $10,000 that does not qualify for the first-time homebuyer exception: $1,000. Total $5,800.","Applies the additional tax to the whole withdrawal. The first-home exception covers up to $10,000."],"wt":["calc","concept","","limit"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Early IRA distributions are taxable; the 10% additional tax is waived on up to $10,000 used for a first home.","from":"2026-01-01","calc":1,"steps":["Income tax = 20,000 x 24% = $4,800","Additional tax = (20,000 - 10,000) x 10% = $1,000","Total = $5,800"]}},{"i":"TCP-I-D-0014","t":"Cal and Dee Ito, who file jointly, expect 2026 modified AGI of $215,000, which includes $70,000 of net investment income. They are considering converting $80,000 from a traditional IRA to a Roth IRA and paying the tax from other funds. Assume the conversion income is taxed at a flat 24% and the net investment income tax rate is 3.8% with a $250,000 threshold for joint filers. How much additional federal tax, including any net investment income tax, does the conversion cause for 2026?","mc":{"s":"Cal and Dee Ito, who file jointly, expect 2026 modified AGI of $215,000, which includes $70,000 of net investment income. They are considering converting $80,000 from a traditional IRA to a Roth IRA and paying the tax from other funds. Assume the conversion income is taxed at a flat 24% and the net investment income tax rate is 3.8% with a $250,000 threshold for joint filers. How much additional federal tax, including any net investment income tax, does the conversion cause for 2026?","d":"","o":["$1,710","$3,040","$19,200","$20,910"],"a":4,"cite":"IRC §408A(d)(3); IRC §1411(a)(1); IRC §1411(b)","rat":"The conversion is ordinary income of $80,000 taxed at 24% ($19,200).","ex":["This is only the net investment income tax the conversion triggers ($1,710). The conversion income is also taxed at 24%.","Applies the 3.8% tax to the conversion itself and leaves out the income tax. A Roth conversion is ordinary income, and it is not net investment income; it only raises modified AGI.","Counts only the income tax on the conversion and misses the net investment income tax it triggers by raising modified AGI over the threshold.","The conversion is ordinary income of $80,000 taxed at 24% ($19,200). It is not investment income, but it raises modified AGI to $295,000, which is $45,000 over the threshold. The 3.8% tax applies to the lesser of net investment income ($70,000) or the excess ($45,000), or $1,710. Total $20,910."],"wt":["trap","concept","trap",""],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"The net investment income tax applies to the lesser of net investment income or modified AGI above the threshold, and a Roth conversion increases modified AGI even though it is not investment income.","from":"2026-01-01","calc":1,"steps":["Conversion income tax = 80,000 x 24% = 19,200","Modified AGI after conversion = 215,000 + 80,000 = 295,000; excess over 250,000 = 45,000","Net investment income tax = 3.8% x min(70,000, 45,000) = 1,710 (before conversion the excess was 0)","Additional tax = 19,200 + 1,710 = 20,910"]}},{"i":"TCP-I-D-0015","t":"Pete Novak, age 60, separated from service in 2026. His 401(k) account holds only employer stock with a cost basis of $100,000 and a value of $400,000, and he takes a lump-sum distribution of the entire account in 2026. Option A: take the stock in kind, pay tax on the $100,000 basis now, and sell the stock 18 months later for $450,000. Option B: roll the account to a traditional IRA and later withdraw $450,000 in one year, after the stock has grown to that value. Assume his ordinary rate is 24% and his long-term capital gain rate is 15% in all years, the 10% early distribution tax does not apply, and ignore the time value of money. How much less total federal income tax does Option A produce than Option B?","mc":{"s":"Pete Novak, age 60, separated from service in 2026. His 401(k) account holds only employer stock with a cost basis of $100,000 and a value of $400,000, and he takes a lump-sum distribution of the entire account in 2026. Option A: take the stock in kind, pay tax on the $100,000 basis now, and sell the stock 18 months later for $450,000. Option B: roll the account to a traditional IRA and later withdraw $450,000 in one year, after the stock has grown to that value. Assume his ordinary rate is 24% and his long-term capital gain rate is 15% in all years, the 10% early distribution tax does not apply, and ignore the time value of money. How much less total federal income tax does Option A produce than Option B?","d":"","o":["$4,500","$31,500","$40,500","$76,500"],"a":2,"cite":"IRC §402(e)(4); Reg. §1.402(a)-1(b); IRC §72(t)(2)(A)(v)","rat":"Option A: $100,000 basis is ordinary income now ($24,000).","ex":["Gives Option A the favorable rate only on the $50,000 of appreciation after distribution ($50,000 x 9%). The $300,000 of net unrealized appreciation gets long-term capital gain treatment.","Option A: $100,000 basis is ordinary income now ($24,000). The $300,000 of net unrealized appreciation is long-term gain when sold, and so is the $50,000 of later growth because he held the shares more than a year after distribution ($350,000 x 15% = $52,500). Total $76,500. Option B taxes $450,000 as ordinary income at 24% ($108,000). Difference $31,500.","Applies the capital gain rate to the whole $450,000. The $100,000 basis is taxed as ordinary income when distributed.","This is the total tax under Option A ($76,500), not the savings compared with Option B."],"wt":["calc","","concept","trap"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"On a lump-sum distribution of employer stock, tax on the net unrealized appreciation is deferred to the sale and taxed as long-term gain, while the cost basis is ordinary income at distribution; a rollover to an IRA taxes everything as ordinary income.","from":"2026-01-01","calc":1,"steps":["Net unrealized appreciation = 400,000 - 100,000 = 300,000; growth after distribution = 450,000 - 400,000 = 50,000","Option A tax = 100,000 x 24% + 300,000 x 15% + 50,000 x 15% = 24,000 + 45,000 + 7,500 = 76,500","Option B tax = 450,000 x 24% = 108,000","Difference = 108,000 - 76,500 = 31,500"]}},{"i":"TCP-I-D-0016","t":"Sylvia Tran, single, age 62, needs $100,000 of cash in 2026 and has no other income. She can raise it from her traditional IRA, from a taxable brokerage account of long-term holdings whose basis is 10% of their value, or from both. Plan 1: withdraw $100,000 from the IRA. Plan 2: sell $100,000 of brokerage holdings. Plan 3: withdraw $50,000 from the IRA and sell $50,000 of brokerage holdings. Assume a $16,100 standard deduction, ordinary rates of 10% on taxable income up to $12,400, 12% up to $50,400 and 22% up to $105,700, and long-term capital gain rates of 0% on taxable income up to $49,450 and 15% above that, with capital gain stacked on top of ordinary taxable income. Ignore the net investment income tax and state taxes. Which plan has the lowest 2026 federal income tax?","mc":{"s":"Sylvia Tran, single, age 62, needs $100,000 of cash in 2026 and has no other income. She can raise it from her traditional IRA, from a taxable brokerage account of long-term holdings whose basis is 10% of their value, or from both. Plan 1: withdraw $100,000 from the IRA. Plan 2: sell $100,000 of brokerage holdings. Plan 3: withdraw $50,000 from the IRA and sell $50,000 of brokerage holdings. Assume a $16,100 standard deduction, ordinary rates of 10% on taxable income up to $12,400, 12% up to $50,400 and 22% up to $105,700, and long-term capital gain rates of 0% on taxable income up to $49,450 and 15% above that, with capital gain stacked on top of ordinary taxable income. Ignore the net investment income tax and state taxes. Which plan has the lowest 2026 federal income tax?","d":"","o":["Plan 1, with tax of about $13,170","Plan 3, with tax of about $8,238","Plans 2 and 3 equally, because both use the 0% capital gain rate on part of the gain","Plan 2, with tax of about $3,668"],"a":4,"cite":"IRC §1(h); IRC §408(d)(1); IRC §63(c)","rat":"The sale produces $90,000 of long-term gain and no ordinary income.","ex":["Withdrawing all $100,000 from the IRA makes it all ordinary income taxed up to the 22% bracket, the highest tax of the three plans.","The $50,000 IRA withdrawal uses up the standard deduction against ordinary income and pushes the gain into the 15% range, so the tax is higher than selling the brokerage holdings alone.","Both plans use some 0% bracket, but Plan 3 has ordinary income that occupies part of it and more gain above it, so the two taxes differ.","The sale produces $90,000 of long-term gain and no ordinary income. The standard deduction reduces the gain to $73,900 of taxable income, of which $49,450 is at 0% and $24,450 at 15%: about $3,668."],"wt":["concept","trap","concept",""],"tags":{"area":"I","group":"D","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Long-term capital gain is taxed at 0% only to the extent it fits in the low bracket after ordinary income, and the standard deduction can offset gain, so a withdrawal order that adds ordinary income can cost more than selling appreciated assets.","from":"2026-01-01","calc":1,"steps":["Plan 1: taxable income = 100,000 - 16,100 = 83,900; tax = 1,240 + 4,560 + 22% x 33,500 = 13,170","Plan 2: gain = 100,000 - 10,000 = 90,000; taxable income = 90,000 - 16,100 = 73,900; tax = 15% x (73,900 - 49,450) = 3,668","Plan 3: ordinary taxable income = 50,000 - 16,100 = 33,900, tax 3,820; gain 45,000 stacked above it, 15,550 at 0% and 29,450 at 15% = 4,418; total 8,238","Plan 2 has the lowest tax"]}}],"17":[{"i":"TCP-I-D-0007","t":"Which statement about investment risk is correct?","mc":{"s":"Which statement about investment risk is correct?","d":"","o":["Long-term fixed-rate bonds are less sensitive to changes in interest rates than short-term fixed-rate bonds","Interest on a municipal bond is exempt from federal income tax, so the bond carries no risk of default","An investment-grade corporate bond carries no market price risk if it is held to maturity","Holding shares of many unrelated companies reduces company-specific risk but does not eliminate market risk"],"a":4,"cite":"IRC §103(a); Pub 550","rat":"Diversification removes risk that is unique to an issuer.","ex":["The reverse is true: longer maturities have larger price changes when rates change.","Tax exemption of the interest has no effect on the issuer's ability to pay. Municipal bonds carry credit risk.","Holding to maturity avoids realizing a price loss, but the bond still carries interest rate and credit risk during the holding period.","Diversification removes risk that is unique to an issuer. Risk that affects the whole market remains."],"wt":["concept","trap","trap",""],"tags":{"area":"I","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Diversification reduces company-specific risk; interest rate, credit, and market risks remain for bonds and stocks.","from":"2026-01-01"}}],"18":[{"i":"TCP-I-D-0008","t":"Gina Frost, whose federal marginal rate on ordinary income is 35%, is choosing between a corporate bond and a state municipal bond. The corporate bond pays 5.6% interest, and she is also subject to the 3.8% net investment income tax on it. Ignore state tax. What is the after-tax yield of the corporate bond?","mc":{"s":"Gina Frost, whose federal marginal rate on ordinary income is 35%, is choosing between a corporate bond and a state municipal bond. The corporate bond pays 5.6% interest, and she is also subject to the 3.8% net investment income tax on it. Ignore state tax. What is the after-tax yield of the corporate bond?","d":"","o":["3.43%","3.64%","5.39%","9.15%"],"a":1,"cite":"IRC §1411(a); IRC §61(a)(4); Pub 550","rat":"Interest is taxed at 35% plus 3.8%: 5.6% x (1 - 0.35 - 0.038) = 3.43%.","ex":["Interest is taxed at 35% plus 3.8%: 5.6% x (1 - 0.35 - 0.038) = 3.43%.","Omits the 3.8% net investment income tax.","Applies only the net investment income tax and omits the income tax.","Computes a tax-equivalent yield, which grosses up a tax-free yield, instead of reducing the taxable yield."],"wt":["","concept","concept","trap"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"After-tax yield equals the pre-tax yield multiplied by one minus the total tax rate, including the net investment income tax where it applies.","from":"2026-01-01","calc":1,"steps":["Total rate on the interest = 35% + 3.8% = 38.8%","After-tax yield = 5.6% x (1 - 0.388) = 3.43%"]}},{"i":"TCP-I-D-0009","t":"Two investments each cost $50,000 and are held for 3 years. Investment X is stock that pays $1,500 of qualified dividends a year (taxed at 15%) and is sold at the end for $68,000, with the gain taxed at 15%. Investment Y is a taxable bond fund that pays $2,600 of interest a year, taxed at 32%, and returns the $50,000 of principal. Comparing total after-tax profit divided by cost, which investment has the higher return, and by how many percentage points?","mc":{"s":"Two investments each cost $50,000 and are held for 3 years. Investment X is stock that pays $1,500 of qualified dividends a year (taxed at 15%) and is sold at the end for $68,000, with the gain taxed at 15%. Investment Y is a taxable bond fund that pays $2,600 of interest a year, taxed at 32%, and returns the $50,000 of principal. Comparing total after-tax profit divided by cost, which investment has the higher return, and by how many percentage points?","d":"","o":["Investment X, by 27.64 percentage points","Investment X, by 29.4 percentage points","Investment X, by 19.99 percentage points","Investment Y, by 10.61 percentage points"],"a":1,"cite":"IRC §1(h); IRC §61(a); Pub 550","rat":"X: dividends $3,825 + gain $15,300 after tax = $19,125, or 38.25% of cost.","ex":["X: dividends $3,825 + gain $15,300 after tax = $19,125, or 38.25% of cost. Y: $5,304 after tax, or 10.61%. X is higher by 27.64 points.","Compares pre-tax returns. The question asks for after-tax returns.","Taxes X's dividends and gain at 32% instead of the 15% preferential rate.","Reports Y's return as the margin and picks the wrong investment."],"wt":["","concept","concept","trap"],"tags":{"area":"I","group":"D","skill":"Analysis","diff":2},"asof":"2026-09-29","rl":"Compare investments on after-tax profit; qualified dividends and long-term gains are taxed at lower rates than interest.","from":"2026-01-01","calc":1,"steps":["X after-tax profit = $3,825 + $15,300 = $19,125; return 38.25%","Y after-tax profit = $5,304; return 10.61%","Difference = 27.64 points"]}}],"19":[{"i":"TCP-I-D-0010","t":"Ana Ruiz, a degree candidate at a university, received a $9,000 scholarship in 2026 that was used for $6,000 of tuition and required fees, $1,000 of books required for her courses, and $2,000 of room and board. How much of the scholarship is included in her gross income?","mc":{"s":"Ana Ruiz, a degree candidate at a university, received a $9,000 scholarship in 2026 that was used for $6,000 of tuition and required fees, $1,000 of books required for her courses, and $2,000 of room and board. How much of the scholarship is included in her gross income?","d":"","o":["$0","$2,000","$3,000","$9,000"],"a":2,"cite":"IRC §117(a); IRC §117(b); Pub 970","rat":"Amounts used for tuition, required fees and required books are excluded.","ex":["Excludes the room and board portion. Only qualified tuition and related expenses are excluded.","Amounts used for tuition, required fees and required books are excluded. The $2,000 used for room and board is included in income.","Includes the required books. Books required for courses are qualified expenses.","Includes the whole scholarship even though most of it paid qualified expenses."],"wt":["concept","","concept","concept"],"tags":{"area":"I","group":"D","skill":"Application","diff":1},"asof":"2026-09-29","rl":"A scholarship is excluded to the extent it pays tuition, required fees, and required books, supplies and equipment; room and board is taxable.","from":"2026-01-01","calc":1,"steps":["Excluded = 6,000 + 1,000 = $7,000","Included = 2,000"]}},{"i":"TCP-I-D-0011","t":"Jack Lomax withdrew $10,000 from a 529 plan account for his daughter in 2026 and spent it on a car. The account's earnings were 30% of the balance withdrawn, and Jack's marginal rate is 24%. What is the total of the income tax and the additional tax he owes on the withdrawal?","mc":{"s":"Jack Lomax withdrew $10,000 from a 529 plan account for his daughter in 2026 and spent it on a car. The account's earnings were 30% of the balance withdrawn, and Jack's marginal rate is 24%. What is the total of the income tax and the additional tax he owes on the withdrawal?","d":"","o":["$300","$720","$1,020","$3,400"],"a":3,"cite":"IRC §529(c)(3)(A); IRC §529(c)(6); Pub 970","rat":"The earnings portion, $10,000 x 30% = $3,000, is taxable at 24% ($720) and subject to a 10% additional tax ($300).","ex":["Counts only the additional tax and omits the income tax on earnings.","Omits the 10% additional tax on nonqualified withdrawals.","The earnings portion, $10,000 x 30% = $3,000, is taxable at 24% ($720) and subject to a 10% additional tax ($300). The contribution portion is not taxed. Total $1,020.","Applies both taxes to the whole withdrawal instead of only the earnings."],"wt":["calc","concept","","concept"],"tags":{"area":"I","group":"D","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A nonqualified 529 withdrawal is taxed on the earnings portion only, plus a 10% additional tax on those earnings.","from":"2026-01-01","calc":1,"steps":["Earnings = 10,000 x 30% = $3,000","Income tax = $720; additional tax = $300","Total = $1,020"]}}],"20":[{"i":"TCP-I-D-0012","t":"Carl Price owned a life insurance policy on his own life and named his daughter as the beneficiary. He died in 2026 while still owning the policy. Which statement about the death benefit is correct?","mc":{"s":"Carl Price owned a life insurance policy on his own life and named his daughter as the beneficiary. He died in 2026 while still owning the policy. Which statement about the death benefit is correct?","d":"","o":["It is included in the daughter's gross income as ordinary income and excluded from Carl's gross estate","It is excluded from the daughter's gross income and included in Carl's gross estate","It is excluded from the daughter's gross income and excluded from Carl's gross estate because it passed by beneficiary designation","It is included in the daughter's gross income to the extent it exceeds the premiums Carl paid"],"a":2,"cite":"IRC §101(a); IRC §2042; Pub 525","rat":"Death benefits paid by reason of the insured's death are excluded from income, and proceeds of a policy owned by the insured are included in the estate.","ex":["Death benefits are excluded from the beneficiary's income, and a policy the insured owned is part of the estate.","Death benefits paid by reason of the insured's death are excluded from income, and proceeds of a policy owned by the insured are included in the estate.","Naming a beneficiary does not keep the proceeds out of the estate when the insured owned the policy.","The excess over premiums is excluded from income when paid by reason of death."],"wt":["concept","","trap","concept"],"tags":{"area":"I","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Life insurance proceeds are excluded from the beneficiary's income and are included in the estate when the insured had incidents of ownership.","from":"2026-01-01"}}],"21":[{"i":"TCP-I-D-0013","t":"Dora Eaton's will leaves all of her property to her son. At her death, her 401(k) account named her daughter as the sole beneficiary on the plan's designation form, which she never changed. Who receives the 401(k) account?","mc":{"s":"Dora Eaton's will leaves all of her property to her son. At her death, her 401(k) account named her daughter as the sole beneficiary on the plan's designation form, which she never changed. Who receives the 401(k) account?","d":"","o":["The son, because the will controls the disposition of all of the decedent's property","The son and the daughter equally, because the will and the designation conflict with each other","The daughter, because the designation form controls and the account passes outside the will","The estate, because a beneficiary designation is effective only if the will confirms it"],"a":3,"cite":"IRC §401(a)(9); IRC §2039; Pub 590-B","rat":"Retirement accounts pass by beneficiary designation form and not through probate under the will.","ex":["A will does not override a valid beneficiary designation on a retirement account.","There is no rule that splits conflicting instruments. The designation form governs the account.","Retirement accounts pass by beneficiary designation form and not through probate under the will.","The designation is effective on its own terms and does not need confirmation in the will."],"wt":["concept","trap","","concept"],"tags":{"area":"I","group":"D","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"Assets with a named beneficiary, including retirement accounts and life insurance, pass by the designation and not by the will.","from":"2026-01-01"}}]};
window.PAIRS=[];
